.achievements-hero {
  position: relative;
  background: var(--bg-primary);
  border-radius: var(--r);
  padding: 20px 16px;
  overflow: hidden;
  grid-column: 1;
  grid-row: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--glass-border);
}

.achievements-hero__bg {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background:
    radial-gradient(circle at 20% 50%, var(--brand-dim) 0%, transparent 50%),
    radial-gradient(circle at 80% 50%, var(--brand-dim) 0%, transparent 50%);
  opacity: 0.5;
}

.achievements-hero__content {
  position: relative;
  text-align: center;
  z-index: 1;
}

.achievements-hero__icon-wrapper {
  position: relative;
  display: inline-block;
  margin-bottom: 12px;
}

.achievements-hero__icon {
  position: relative;
  font-size: 40px;
  color: var(--brand);
}

.achievements-hero__title {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 4px 0;
}

.achievements-hero__subtitle {
  font-size: 13px;
  color: var(--text-secondary);
  margin: 0 0 16px 0;
}

.achievements-hero__stats {
  display: flex;
  justify-content: space-around;
  width: 100%;
  gap: 12px;
}

.achievements-hero__stat {
  text-align: center;
}

.achievements-hero__stat-value {
  font-size: 20px;
  font-weight: 700;
  color: var(--brand);
  margin-bottom: 2px;
}

.achievements-hero__stat-label {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: var(--ls-wide);
}

.achievements-disabled-banner {
  margin-top: 12px;
  padding: 8px 12px;
  background: var(--error-bg);
  border: 1px solid var(--error-border);
  border-radius: var(--r-sm);
  color: var(--error);
  font-size: 11px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: center;
}

.achievements-progress {
  grid-column: 1;
  grid-row: 2;
  background: var(--surface-1);
  border: 1px solid var(--glass-border);
  border-radius: var(--r);
  padding: 12px 16px;
}

.achievements-progress--disabled {
  opacity: 0.5;
  pointer-events: none;
  filter: grayscale(0.5);
}

.achievements-progress__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.achievements-progress__label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-primary);
  text-transform: uppercase;
  letter-spacing: var(--ls-wide);
}

.achievements-progress__counter {
  font-size: 11px;
  color: var(--text-secondary);
  font-weight: 500;
}

.achievements-progress__bar-wrapper {
  display: flex;
  align-items: center;
  gap: 10px;
}

.achievements-progress__bar {
  flex: 1;
  height: 16px;
  background: var(--surface-2);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: inset 0 2px 4px var(--shadow-color);
  border: 1px solid var(--glass-border);
}

.achievements-progress__fill {
  position: relative;
  height: 100%;
  background: var(--brand);
  transition: width 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.achievements-progress__percentage {
  font-size: 13px;
  font-weight: 700;
  color: var(--brand);
  min-width: 36px;
  text-align: right;
}

.achievements-toggle {
  grid-column: 1;
  grid-row: 3;
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: var(--surface-1);
  padding: 6px;
  border-radius: var(--r);
  border: 1px solid var(--glass-border);
  align-self: start;
}

.achievements-toggle__btn {
  flex: none;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  padding: 10px 16px;
  background: transparent;
  border: none;
  border-radius: var(--r-sm);
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background-color 0.2s,
    color 0.2s;
  box-sizing: border-box;
}

.achievements-toggle__btn:hover {
  background: var(--glass-hover);
  color: var(--text-primary);
}

.achievements-toggle__btn--active {
  background: var(--brand);
  color: var(--text-on-brand);
}

.achievements-toggle__btn i {
  font-size: 14px;
}

.achievements-unlock-all {
  grid-column: 1;
  grid-row: 4;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--surface-1);
  border: 1px solid var(--glass-border);
  border-radius: var(--r-sm);
  color: var(--brand);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background-color 0.2s,
    color 0.2s;
}

.achievements-unlock-all:hover {
  background: var(--brand);
  color: var(--text-on-brand);
}

.achievements-grid {
  grid-column: 2;
  grid-row: 1 / span 3;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
  grid-auto-rows: max-content;
  align-items: start;
  gap: 12px;
  padding-bottom: 20px;
  overflow-y: auto;
  height: 100%;
  padding-right: 6px;
  box-sizing: border-box;
}

.achievements-grid::-webkit-scrollbar {
  width: 8px;
}

.achievements-grid::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 4px;
}

.achievements-grid::-webkit-scrollbar-thumb {
  background: var(--glass-hover);
  border-radius: 4px;
}

.achievement-card {
  position: relative;
  display: flex;
  gap: 16px;
  background: var(--surface-2);
  border: 1px solid var(--glass-border);
  border-radius: var(--r);
  padding: 16px;
  transition:
    background-color 0.3s cubic-bezier(0.4, 0, 0.2, 1),
    border-color 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  overflow: hidden;
  align-items: center;
  box-sizing: border-box;
}

.achievement-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--brand-dim),
    transparent
  );
  opacity: 0;
  transition: opacity 0.3s;
}

.achievement-card:hover {
  border-color: var(--brand-dim);
  background: var(--surface-3);
}

.achievement-card:hover::before {
  opacity: 1;
}

.achievement-card--unlocked {
  background: var(--surface-3);
  border-color: var(--brand-dim);
}

.achievement-card--unlocked::before {
  background: linear-gradient(
    90deg,
    var(--brand),
    var(--brand-hover),
    var(--brand)
  );
  opacity: 1;
}

.achievement-card--unlocked:hover {
  border-color: var(--brand);
}

.achievement-card--disabled {
  opacity: 0.5;
  pointer-events: none;
  filter: grayscale(0.5);
}

.achievement-card__icon-wrapper {
  position: relative;
  flex-shrink: 0;
  width: 60px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.achievement-card__icon-bg {
  position: absolute;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, var(--surface-2), var(--surface-1));
  border: 2px solid var(--glass-border);
  border-radius: 10px;
  transition:
    background-color 0.3s,
    color 0.3s;
}

.achievement-card--unlocked .achievement-card__icon-bg {
  background: var(--brand-dim);
  border-color: var(--brand);
}

.achievement-card__icon {
  position: relative;
  font-size: 26px;
  color: var(--text-secondary);
  transition:
    background-color 0.3s,
    color 0.3s;
  z-index: 1;
}

.achievement-card--unlocked .achievement-card__icon {
  color: var(--brand);
  animation: iconPop 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes iconPop {
  0% {
    transform: scale(0);
  }
  50% {
    transform: scale(1.2);
  }
  100% {
    transform: scale(1);
  }
}

.achievement-card__checkmark {
  position: absolute;
  bottom: -4px;
  right: -4px;
  width: 20px;
  height: 20px;
  background: var(--brand);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  animation: checkmarkPop 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.3s backwards;
}

@keyframes checkmarkPop {
  0% {
    transform: scale(0);
  }
  100% {
    transform: scale(1);
  }
}

.achievement-card__checkmark i {
  font-size: 10px;
  color: var(--text-on-brand);
}

.achievement-card__content {
  flex: 1;
  min-width: 0;
}

.achievement-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.achievement-card__title {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-secondary);
  margin: 0;
  transition: color 0.3s;
  flex: 1;
}

.achievement-card--unlocked .achievement-card__title {
  color: var(--text-primary);
}

.achievement-card__badges {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.achievement-card__rarity {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  padding: 3px 6px;
  border-radius: 5px;
  letter-spacing: var(--ls-wide);
  white-space: nowrap;
}

.achievement-card__desc {
  font-size: 12.5px;
  color: var(--text-secondary);
  margin: 4px 0 0 0;
  line-height: 1.4;
}

.achievement-card--unlocked .achievement-card__desc {
  color: var(--text-primary);
}

.achievement-card__date {
  font-size: 11px;
  color: var(--text-secondary);
  margin: 6px 0 0 0;
  opacity: 0.75;
}

.achievement-card__lock {
  width: 20px;
  height: 20px;
  background: var(--surface-2);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--glass-border);
  flex-shrink: 0;
}

.achievement-card__lock i {
  font-size: 9px;
  color: var(--text-secondary);
}

.achievement-popup {
  position: fixed;
  bottom: -170px;
  right: 0;
  width: 320px;
  background: var(--surface-2);
  border: none;
  border-radius: 0;
  box-shadow: 0 20px 60px var(--shadow-color);
  z-index: 100000;
  display: flex;
  gap: 0;
  overflow: hidden;
  transition: bottom 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.achievement-popup--show {
  bottom: 0;
}

.achievement-popup--hide {
  bottom: -170px;
  transition: bottom 0.4s ease-in;
}

.achievement-popup__icon-wrapper {
  position: relative;
  width: 72px;
  min-height: 72px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--brand-dim), var(--surface-1));
}

.achievement-popup__icon-bg {
  position: absolute;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.15) 0%,
    transparent 70%
  );
}

.achievement-popup__icon {
  position: relative;
  font-size: 28px;
  color: #fff;
  z-index: 1;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.3));
}

.achievement-popup__content {
  flex: 1;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.achievement-popup__badge {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  color: #ffd700;
  margin-bottom: 4px;
  letter-spacing: var(--ls-wide);
}

.achievement-popup__badge i {
  font-size: 12px;
}

.achievement-popup__title {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 2px;
  line-height: 1.3;
}

.achievement-popup__desc {
  font-size: 11.5px;
  color: var(--text-secondary);
  margin-bottom: 6px;
  line-height: 1.4;
}

.achievement-popup[data-rarity="common"] .achievement-popup__icon-wrapper {
  background: linear-gradient(135deg, #cd7f32, #8b5e3c);
}
.achievement-popup[data-rarity="uncommon"] .achievement-popup__icon-wrapper {
  background: linear-gradient(135deg, #a0a0a0, #707070);
}
.achievement-popup[data-rarity="rare"] .achievement-popup__icon-wrapper {
  background: linear-gradient(135deg, #ffd700, #b8860b);
}
.achievement-popup[data-rarity="epic"] .achievement-popup__icon-wrapper {
  background: linear-gradient(135deg, #8b5cf6, #5b2c9f);
}
.achievement-popup[data-rarity="legendary"] .achievement-popup__icon-wrapper {
  background: linear-gradient(135deg, #ff4500, #cc3700);
}

.activity-popup {
  position: fixed;
  bottom: -120px;
  right: 0;
  width: 300px;
  background: var(--surface-2);
  border: 1px solid var(--glass-border);
  border-radius: 0;
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.65);
  z-index: 100000;
  display: flex;
  align-items: stretch;
  overflow: hidden;
  transition: bottom 0.45s cubic-bezier(0.34, 1.56, 0.64, 1);
  cursor: pointer;
}

.activity-popup--show {
  bottom: 0;
}

.activity-popup--hide {
  bottom: -120px;
  transition: bottom 0.35s ease-in;
}

.activity-popup__avatar-col {
  width: 64px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-primary);
}

.activity-popup__avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
}

.activity-popup__avatar--default {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--surface-2);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-size: 15px;
}

.activity-popup__body {
  flex: 1;
  padding: 10px 14px 10px 10px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
}

.activity-popup__name {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.3;
}

.activity-popup__action {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.3;
  margin-bottom: 4px;
}

.activity-popup__game {
  display: flex;
  align-items: center;
  gap: 6px;
}

.activity-popup__game-icon {
  width: 18px;
  height: 18px;
  border-radius: 3px;
  object-fit: cover;
  flex-shrink: 0;
}

.activity-popup__game-icon--fa {
  font-size: 14px;
  color: var(--text-secondary);
  flex-shrink: 0;
}

.activity-popup__game-name {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-secondary);
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.achievements-scroll {
  height: 100%;
  overflow-y: auto;
  padding-right: 12px;
}

.achievements-scroll::-webkit-scrollbar {
  width: 8px;
}

.achievements-scroll::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 4px;
}

.achievements-scroll::-webkit-scrollbar-thumb {
  background: var(--glass-hover);
  border-radius: 4px;
}

.achievements-content {
  background: var(--bg-primary);
  padding: 16px;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden;
}

.achievements-scroll {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-rows: auto auto 1fr;
  gap: 16px;
  height: 100%;
  overflow: hidden;
  padding-right: 0;
}

@media (max-width: 768px) {
  .achievements-scroll {
    display: block;
    overflow-y: auto;
  }
  .achievements-toggle {
    display: flex;
    flex-direction: row;
    margin-bottom: 16px;
  }
  .achievements-toggle__btn {
    flex: 1;
    justify-content: center;
  }
  .achievements-grid {
    display: grid;
    grid-template-columns: 1fr;
    overflow-y: visible;
    height: auto;
  }
  .achievements-hero {
    margin-bottom: 16px;
  }
  .achievements-progress {
    margin-bottom: 16px;
  }
  .achievements-unlock-all {
    margin-bottom: 16px;
  }
  .achievement-popup {
    width: calc(100% - 40px);
    bottom: -170px;
    right: 0;
  }
  .achievement-popup--show {
    bottom: 0;
  }
  .achievements-hero__stats {
    gap: 24px;
  }
}
.converter-window {
  min-width: 500px;
  min-height: 400px;
}

.converter-container {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: rgba(18, 18, 24, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: #f1f1f7;
  font-family: var(--font-ui);
  user-select: none;
  overflow: hidden;
}

.converter-layout {
  display: flex;
  flex: 1;
  overflow: hidden;
}

.converter-sidebar {
  width: 260px;
  background: rgba(255, 255, 255, 0.02);
  border-right: 1px solid rgba(255, 255, 255, 0.06);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow-y: auto;
}

.converter-content {
  flex: 1;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  overflow-y: auto;
  background: rgba(0, 0, 0, 0.15);
}

.converter-section-title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--ls-wide);
  color: var(--text-muted);
  margin-bottom: 8px;
}

.file-info-box {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.file-info-item {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
}

.file-info-label {
  color: rgba(255, 255, 255, 0.5);
}

.file-info-val {
  font-weight: 500;
  max-width: 150px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.control-label {
  font-size: 13px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.85);
}

.control-input,
.control-select {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  color: #fff;
  padding: 8px 12px;
  font-size: 14px;
  outline: none;
  transition:
    background-color 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
}

.control-input:focus,
.control-select:focus {
  border-color: var(--brand);
  box-shadow: 0 0 0 2px var(--brand);
  background: rgba(255, 255, 255, 0.09);
}

.control-row {
  display: flex;
  gap: 12px;
}

.control-row .control-group {
  flex: 1;
  min-width: 0;
}

.options-panel {
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.slider-container {
  display: flex;
  align-items: center;
  gap: 12px;
}

.slider-val {
  font-size: 13px;
  font-family: var(--font-mono);
  min-width: 32px;
}

.checkbox-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  cursor: pointer;
}

.checkbox-label input {
  cursor: pointer;
}

.preview-container {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.2);
  padding: 12px;
  max-height: 200px;
  overflow: auto;
  font-family: var(--font-mono);
  font-size: 12px;
  white-space: pre-wrap;
}

.preview-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  text-align: left;
}

.preview-table th,
.preview-table td {
  padding: 6px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  max-width: 150px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.preview-table th {
  background: rgba(255, 255, 255, 0.05);
  font-weight: 600;
  color: rgba(255, 255, 255, 0.7);
}

.converter-footer {
  padding: 16px 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  display: flex;
  align-items: center;
  justify-content: space-between;
