  overflow: auto;
}
.desktop.stk-no-taskbar {
  bottom: 0;
}
html.is-mobile .desktop.stk-no-taskbar {
  bottom: 0;
}

.icon {
  position: absolute;
  width: var(--icon-w);
  height: var(--icon-h);
  min-height: var(--icon-h);
  max-height: var(--icon-h);
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  text-align: center;
  color: var(--text-primary, #ffffff);
  padding: 0.3rem 0;
  font-size: 0.75rem;
  text-shadow: 0 1px 3px var(--shadow-color, rgba(0, 0, 0, 0.9));
  border: 1px solid transparent;
  border-radius: 3px;
  overflow: hidden;
  flex-shrink: 0;
  transition:
    background 0.15s,
    border-color 0.15s;
}

.icon img,
.icon svg {
  width: var(--icon-img-s) !important;
  height: var(--icon-img-s) !important;
  max-width: var(--icon-img-s) !important;
  max-height: var(--icon-img-s) !important;
  min-width: var(--icon-img-s) !important;
  min-height: var(--icon-img-s) !important;
  flex-shrink: 0;
  border-radius: var(--r-xl);
  margin-bottom: 0.3rem;
  pointer-events: none;
  transition: transform 0.15s;
}

.icon > div:first-child:not(:last-child) {
  width: var(--icon-img-s) !important;
  height: var(--icon-img-s) !important;
  max-width: var(--icon-img-s) !important;
  max-height: var(--icon-img-s) !important;
  min-width: var(--icon-img-s) !important;
  min-height: var(--icon-img-s) !important;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.3rem;
  overflow: hidden;
  padding: 0;
}

.icon > div:first-child:not(:last-child) img,
.icon > div:first-child:not(:last-child) svg {
  max-width: 100% !important;
  max-height: 100% !important;
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  margin-bottom: 0;
}

.icon > div:first-child:not(:last-child) i {
  margin-bottom: 0;
}

.icon > i:first-child {
  width: var(--icon-img-s) !important;
  height: var(--icon-img-s) !important;
  max-width: var(--icon-img-s) !important;
  max-height: var(--icon-img-s) !important;
  min-width: var(--icon-img-s) !important;
  min-height: var(--icon-img-s) !important;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.3rem;
  font-size: calc(var(--icon-img-s) * 0.58);
}

.icon i {
  color: var(--brand);
}

.desktop-file-icon--fa-wrapper {
  width: var(--icon-img-s);
  height: var(--icon-img-s);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  color: var(--brand);
}

.icon div {
  font-size: 0.95em;
  line-height: 1.2;
  color: var(--text-primary, #f5f5f5);
  text-shadow: 0 1px 3px var(--shadow-color, rgba(0, 0, 0, 0.9));
  word-break: normal;
  overflow-wrap: anywhere;
  width: 100%;
  max-width: 100%;
  padding: 0 2px;
  box-sizing: border-box;
}

.icon > div:last-child {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  line-clamp: 2;
  overflow: hidden;
  text-overflow: ellipsis;
  overflow-wrap: anywhere;
  word-break: normal;
  line-height: 1.2;
  white-space: normal;
  text-align: center;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  height: 2.4em;
  min-height: 2.4em;
  max-height: 2.4em;
  flex-shrink: 0;
  color: var(--text-primary, #f5f5f5);
  text-shadow: 0 1px 3px var(--shadow-color, rgba(0, 0, 0, 0.9));
  font-size: 0.95em;
  padding: 0 2px;
  box-sizing: border-box;
}

.icon.is-renaming {
  height: auto;
  max-height: none;
  overflow: visible;
}

.icon.is-renaming > div:last-child {
  display: block;
  -webkit-line-clamp: unset;
  line-clamp: unset;
  overflow: visible;
}

.icon:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.2);
}

.icon:hover img {
  transform: scale(1.05);
}

.icon.selected {
  width: var(--icon-w);
  height: var(--icon-h);
  min-height: var(--icon-h);
  max-height: var(--icon-h);
  box-sizing: border-box;
  padding: 0.3rem 0;
  border-width: 1px;
  border-style: solid;
  background: rgba(0, 120, 215, 0.3);
  border-color: rgba(0, 120, 215, 0.6);
}

.icon.selectable img {
  pointer-events: none;
}

@media (max-width: 768px) {
  .icon {
    width: 70px;
    height: 100px;
    min-height: 100px;
    max-height: 100px;
    box-sizing: border-box;
    overflow: hidden;
    font-size: 0.7rem;
  }

  .icon img,
  .icon svg {
    width: 55px;
    height: 55px;
  }
}

@media (max-width: 480px) {
  .icon {
    width: 60px;
    height: 92px;
    min-height: 92px;
    max-height: 92px;
    box-sizing: border-box;
    overflow: hidden;
    font-size: 0.65rem;
  }

  .icon img,
  .icon svg {
    width: 48px;
    height: 48px;
  }
}

.window {
  position: var(--wm-window-position, absolute);
  min-width: 200px;
  min-height: 120px;
  display: flex;
  flex-direction: column;
  z-index: 10;
  border: 1px solid var(--glass-border);
  overflow: var(--wm-window-overflow, hidden);
  backdrop-filter: blur(24px);
  box-shadow: 0 1.1em 40px rgba(0, 0, 0, 0.6);
  color: var(--tx1);
  outline: none;
  transition:
    box-shadow 0.16s cubic-bezier(0.2, 0, 0, 1),
    filter 0.16s cubic-bezier(0.2, 0, 0, 1);
}

.window.snapping {
  transition:
    width 160ms cubic-bezier(0.16, 1, 0.3, 1),
    height 160ms cubic-bezier(0.16, 1, 0.3, 1),
    top 160ms cubic-bezier(0.16, 1, 0.3, 1),
    left 160ms cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.window.dragging {
  pointer-events: none;
}

.window.magnetized {
  box-shadow:
    0 0 0 2px color-mix(in oklch, var(--brand) 55%, transparent),
    0 8px 24px rgba(0, 0, 0, 0.35);
  transition: box-shadow 0.12s ease;
}

.window.snapping-preview {
  opacity: 0.92;
  outline: 2px solid color-mix(in oklch, var(--brand) 35%, transparent);
  outline-offset: -2px;
}

@keyframes wa-fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes wa-scale-in {
  from {
    transform: scale(0.82);
    opacity: 0;
  }

  60% {
    transform: scale(1.015);
    opacity: 1;
  }

  to {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes wa-source-in {
  from {
    transform: translate(var(--wa-ox, 0), var(--wa-oy, 0)) scale(0.1);
    opacity: 0;
  }

  60% {
    transform: translate(0, 0) scale(1.04);
    opacity: 1;
  }

  to {
    transform: translate(0, 0) scale(1);
    opacity: 1;
  }
}

@keyframes wa-slide-up-in {
  from {
    transform: translateY(60px);
    opacity: 0;
  }

  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes wa-slide-left-in {
  from {
    transform: translateX(-60px);
    opacity: 0;
  }

  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes wa-slide-right-in {
  from {
    transform: translateX(60px);
    opacity: 0;
  }

  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes wa-glass-blur-in {
  from {
    filter: blur(14px);
    opacity: 0;
    transform: scale(0.95);
  }

  60% {
    filter: blur(2px);
    opacity: 1;
    transform: scale(1.02);
  }

  to {
    filter: blur(0);
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes wa-slide-in-growth {
  from {
    opacity: 0;
    transform: perspective(300px) scale(0.5) rotateY(-20deg);
  }
  70% {
    opacity: 1;
  }
  to {
    opacity: 1;
    transform: perspective(300px) scale(1) rotateY(0deg);
  }
}

@keyframes wa-fade-out {
  from {
    opacity: 1;
  }

  to {
    opacity: 0;
  }
}

@keyframes wa-scale-out {
  from {
    transform: scale(1);
    opacity: 1;
  }

  to {
    transform: scale(0.82);
    opacity: 0;
  }
}

@keyframes wa-source-out {
  from {
    transform: translate(0, 0) scale(1);
    opacity: 1;
  }

  to {
    transform: translate(var(--wa-ox, 0), var(--wa-oy, 0)) scale(0.05);
    opacity: 0;
  }
}

@keyframes wa-slide-down-out {
  from {
    transform: translateY(0);
    opacity: 1;
  }

  to {
    transform: translateY(80px);
    opacity: 0;
  }
}

@keyframes wa-burn-out {
  0% {
    filter: brightness(1) contrast(1) saturate(1);
    opacity: 1;
    clip-path: inset(0 0 0 0 round 8px);
  }

  30% {
    filter: brightness(2.5) contrast(1.4) saturate(2);
  }

  60% {
    filter: brightness(4) contrast(2) saturate(3) hue-rotate(30deg);
    clip-path: inset(0 0 60% 0 round 8px);
    opacity: 0.6;
  }

  100% {
    filter: brightness(8) contrast(3) saturate(4);
    clip-path: inset(0 0 100% 0 round 8px);
    opacity: 0;
  }
}

@keyframes wa-dock-zoom-out {
  from {
    transform: translate(0, 0) scale(1);
    opacity: 1;
  }

  to {
    transform: translate(var(--wa-ox, 0), var(--wa-oy, 0)) scale(0.1)
      skewY(8deg);
    opacity: 0;
  }
}

@keyframes wa-magic-lamp {
  0% {
    transform: translate(0, 0) scale(1) perspective(600px) rotateX(0deg);
    opacity: 1;
  }

  40% {
    transform: translate(
        calc(var(--wa-ox, 0) * 0.3),
        calc(var(--wa-oy, 0) * 0.3)
      )
      scale(0.7) perspective(600px) rotateX(12deg);
    opacity: 0.8;
  }

  100% {
    transform: translate(var(--wa-ox, 0), var(--wa-oy, 0)) scale(0.04)
      perspective(600px) rotateX(30deg);
    opacity: 0;
  }
}

.wa-focus-glow {
  animation: wa-focus-pulse 0.5s ease-out forwards;
}

@keyframes wa-focus-pulse {
  0% {
    box-shadow:
      0 1.1em 40px rgba(0, 0, 0, 0.6),
      0 0 0 3px rgba(var(--brand-rgb, 79, 158, 255), 0.6);
  }

  60% {
    box-shadow:
      0 1.1em 40px rgba(0, 0, 0, 0.6),
      0 0 0 8px rgba(var(--brand-rgb, 79, 158, 255), 0.15);
  }

  100% {
    box-shadow: 0 1.1em 40px rgba(0, 0, 0, 0.6);
  }
}

.wa-z-lift {
  box-shadow:
    0 24px 64px rgba(0, 0, 0, 0.75),
    0 8px 24px rgba(0, 0, 0, 0.45) !important;
}

@keyframes wa-wobble-settle-anim {
  0% {
    transform: skewX(-3deg) scaleX(1.02);
  }

  25% {
    transform: skewX(2deg) scaleX(0.99);
  }

  50% {
    transform: skewX(-1deg) scaleX(1.005);
  }

  75% {
    transform: skewX(0.5deg);
  }

  100% {
    transform: skewX(0);
  }
}

@keyframes wa-start-expand {
  from {
    transform: scale(0.94) translateY(8px);
    opacity: 0;
  }

  to {
    transform: scale(1) translateY(0);
    opacity: 1;
  }
}

@keyframes wa-start-collapse {
  from {
    transform: scale(1) translateY(0);
    opacity: 1;
  }

  to {
    transform: scale(0.94) translateY(8px);
    opacity: 0;
  }
}

@keyframes wa-ctx-pop {
  from {
    transform: scale(0.88);
    opacity: 0;
  }

  to {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes wa-notif-in {
  from {
    transform: translateX(110%);
    opacity: 0;
  }

  60% {
    transform: translateX(-6%);
    opacity: 1;
  }

  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes wa-ws-left {
  0% {
    transform: translateX(0);
  }

  40% {
    transform: translateX(-30px);
  }

  100% {
    transform: translateX(0);
  }
}

@keyframes wa-ws-right {
  0% {
    transform: translateX(0);
  }

  40% {
    transform: translateX(30px);
  }

  100% {
    transform: translateX(0);
  }
}

.wa-ripple {
  position: fixed;
  width: 6px;
  height: 6px;
  border-radius: 25px;
  background: rgba(var(--brand-rgb, 79, 158, 255), 0.45);
  transform: translate(-50%, -50%) scale(0);
  pointer-events: none;
  z-index: 999999;
  animation: wa-ripple-expand 0.35s cubic-bezier(0.22, 1, 0.36, 1) forwards;
