@keyframes wa-ripple-expand {
  0% {
    transform: translate(-50%, -50%) scale(0);
    opacity: 0.8;
  }

  60% {
    transform: translate(-50%, -50%) scale(28);
    opacity: 0.3;
  }

  100% {
    transform: translate(-50%, -50%) scale(40);
    opacity: 0;
  }
}

@keyframes popDown {
  0% {
    transform: scale(0.85);
    opacity: 0;
  }

  70% {
    transform: scale(1.04);
    opacity: 1;
  }

  100% {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes popUp {
