    opacity var(--dock-anim-speed) ease,
    transform var(--dock-anim-speed) ease;
  transform-origin: center bottom;
}

.mac-dock[data-position="bottom"] {
  bottom: var(--inset);
  left: 50%;
  transform: translateX(-50%) scale(var(--dock-scale));
  flex-direction: row;
  align-items: flex-end;
}

.mac-dock[data-position="left"] {
  left: var(--inset);
  top: 50%;
  transform: translateY(-50%) scale(var(--dock-scale));
  flex-direction: column;
  align-items: flex-start;
}

.mac-dock[data-position="right"] {
  right: var(--inset);
