.session-overlay * {
  font-family: inherit;
}

.session-wallpaper {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: -2;
}

.session-background {
  position: absolute;
  inset: 0;
  backdrop-filter: blur(12px) brightness(0.5);
  z-index: -1;
}

.session-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  z-index: 1;
  width: 100%;
  pointer-events: none;
  position: relative;
}

.session-content > * {
  pointer-events: auto;
}

.session-extra {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  pointer-events: none;
}

.session-extra > * {
  pointer-events: auto;
}

.session-time {
  font-size: 80px;
  font-weight: 200;
  letter-spacing: -2px;
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.session-date {
  font-size: 24px;
  font-weight: 400;
  margin-top: -16px;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.5);
  margin-bottom: 32px;
}

.session-brand {
  display: none;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: 6px;
  text-transform: uppercase;
  color: var(--text-primary);
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.5);
  opacity: 0.9;
}

.avatar-edit-btn {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 26px;
  height: 26px;
  border-radius: 25px;
  background: var(--brand);
  border: 2px solid var(--glass-border);
  color: var(--text-on-brand);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  transition:
    background-color 0.2s,
    color 0.2s;
  z-index: 3;
}

.avatar-edit-btn:hover {
  transform: scale(1.1);
  box-shadow: 0 4px 12px var(--brand-glow);
}

.login-center-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
}

.user-carousel-row {
  display: flex;
  overflow-x: auto;
  gap: 32px;
  padding: 20px calc(50vw - 48px);
  scroll-behavior: smooth;
  white-space: nowrap;
  width: 100vw;
  box-sizing: border-box;
  align-items: center;

  scrollbar-width: none;
  -ms-overflow-style: none;
}

.user-carousel-row::-webkit-scrollbar {
  display: none;
}

.user-carousel-tile {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  background: none;
  border: none;
  cursor: pointer;
  flex-shrink: 0;
  transition:
    transform 0.25s ease,
    opacity 0.25s ease;
  opacity: 0.5;
  padding: 0;
}

.user-carousel-tile:hover {
  opacity: 0.8;
}

.user-carousel-tile.selected {
  opacity: 1;
  transform: scale(1);
}

.carousel-avatar-wrap {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.user-carousel-tile img {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid transparent;
  transition:
    border-color 0.2s,
    width 0.25s ease,
    height 0.25s ease,
    box-shadow 0.25s ease;
}

.user-carousel-tile.selected img {
  width: 96px;
  user-select: none;
  -webkit-user-drag: none;
  height: 96px;
  border-color: var(--brand);
  box-shadow: 0 0 24px var(--brand-glow);
}

.user-carousel-tile span {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary);
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.6);
  opacity: 0;
  transition: opacity 0.2s;
}

.user-carousel-tile.selected span {
  font-size: 16px;
  font-weight: 600;
  opacity: 1;
}

.system-actions-row {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.session-selector {
  position: fixed;
  bottom: 32px;
  left: 32px;
  z-index: 20;
}

.session-modes {
  display: flex;
  align-items: center;
  gap: 10px;
}

.session-modes-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.session-mode-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 76px;
  padding: 8px 10px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  transition:
    background-color 0.15s,
    color 0.15s,
    border-color 0.15s;
  user-select: none;
}

.session-mode-btn svg {
  width: 35px;
  height: 35px;
}

.session-mode-btn i {
  font-size: 30px;
  width: 30px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.session-mode-btn:hover {
  background: var(--glass-hover);
  color: var(--text-primary);
}

.session-mode-btn.active {
  border-color: var(--brand);
  color: var(--text-primary);
  background: color-mix(in srgb, var(--brand) 18%, transparent);
}

.action-button {
  padding: 12px 32px;
  border-radius: 24px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  backdrop-filter: blur(32px);
  color: var(--text-primary);
  font-size: 18px;
  font-weight: 500;
  cursor: pointer;
  transition:
    background-color 0.2s,
    color 0.2s;
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 200px;
  justify-content: center;
}

.action-button:hover {
  background: var(--glass-hover);
  transform: translateY(-2px);
  border-color: var(--brand);
}

.action-button:focus {
  outline: 2px solid white;
  outline-offset: 4px;
}

.system-icon {
  width: 44px;
  height: 44px;
  border-radius: 25px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  transition:
    background-color 0.2s,
    color 0.2s;
}

.system-icon:hover {
  background: var(--glass-hover);
  color: var(--brand);
  transform: translateY(-2px);
  border-color: var(--brand);
}

.system-icon:focus {
  outline: 2px solid white;
  outline-offset: 4px;
}

.avatar-edit-modal {
  position: fixed;
  inset: 0;
  z-index: 9999999;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(8px);
}

.modal-content {
  background: var(--bg-primary);
  border: 1px solid var(--glass-border);
  border-radius: 14px;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.65);
  backdrop-filter: blur(32px);
  max-width: 500px;
  width: 90%;
  max-height: 85vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px;
  border-bottom: 1px solid var(--glass-border);
}

.modal-header h3 {
  font-size: 18px;
  font-weight: 600;
  margin: 0;
}

.modal-close {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 16px;
  padding: 8px;
  transition:
    background-color 0.2s,
    color 0.2s;
}

.modal-close:hover {
  color: var(--brand);
}

.modal-body {
  padding: 20px;
  overflow-y: auto;
}

.avatar-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(64px, 64px));
  gap: 12px;
  margin-bottom: 16px;
  overflow-y: auto;
}

.avatar-tile {
  width: 64px;
  height: 64px;
  border-radius: 25px;
  overflow: hidden;
  cursor: pointer;
  border: 2px solid transparent;
  transition:
    background-color 0.2s,
    color 0.2s;
}

.avatar-tile img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.avatar-tile:hover {
  transform: scale(1.05);
  border-color: var(--glass-border);
}

.avatar-tile.active {
  border-color: var(--brand);
  box-shadow: 0 0 15px var(--brand-glow);
}

.session-overlay.exit {
  animation: fadeOut 0.5s forwards ease-in;
  pointer-events: none;
}

@keyframes fadeOut {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(-100%);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: scale(1.05);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.preview-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.user-history-tile {
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  padding: 10px;
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  transition:
    background-color 0.2s,
    color 0.2s;
}

.user-history-tile:hover {
  background: var(--glass-hover);
  transform: translateX(4px);
  border-color: var(--glass-border);
}

.user-history-tile.selected {
  border-color: var(--brand);
  box-shadow: 0 0 15px var(--brand-glow);
}

.user-history-tile img {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  object-fit: cover;
  flex-shrink: 0;
}

.user-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.user-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.user-last-login {
  font-size: 10px;
  color: var(--text-secondary);
}

.lock-time {
  font-size: 80px;
  font-weight: 200;
  letter-spacing: -2px;
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.lock-date {
  font-size: 24px;
  font-weight: 400;
  margin-top: -16px;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.5);
  margin-bottom: 32px;
}

#lock-unlock-btn {
  margin-top: 32px;
  padding: 12px 32px;
  border-radius: 24px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  backdrop-filter: blur(32px);
  color: var(--text-primary);
  font-size: 18px;
  font-weight: 500;
  cursor: pointer;
  transition:
    background-color 0.2s,
    color 0.2s;
  display: flex;
  align-items: center;
  gap: 12px;
}

#lock-unlock-btn:hover {
  background: var(--glass-hover);
  transform: translateY(-2px);
}

#lock-unlock-btn:focus {
  outline: 2px solid white;
  outline-offset: 4px;
}

.session-overlay.sleep {
  pointer-events: none;
}

.session-overlay.sleep .session-wallpaper {
  animation-play-state: paused;
}

.session-overlay.sleep .session-content,
.session-overlay.sleep .session-background,
.session-overlay.sleep .avatar-edit-modal {
  animation-play-state: paused;
}

.sleep-overlay {
  position: fixed;
  inset: 0;
  background: #000;
  z-index: 999999;
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}

.session-overlay.sleep .sleep-overlay {
  opacity: 1;
  pointer-events: none;
}

.sleep-wake-layer {
  position: fixed;
  inset: 0;
  z-index: 1000000;
  pointer-events: auto;
}

.session-content.extra-hidden .session-extra {
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  transition:
    opacity 0.3s ease,
    visibility 0s linear 0.3s;
}

.session-content.extra-visible .session-extra {
  opacity: 1;
  pointer-events: auto;
  visibility: visible;
  transition: opacity 0.3s ease;
}

.session-activity-panel {
  border-radius: 10px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  padding: 10px 12px;
}

.session-news-list {
  overflow-y: auto;
  flex: 1 1 auto;
  min-height: 140px;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.session-news-list::-webkit-scrollbar {
  width: 8px;
}

.session-news-list::-webkit-scrollbar-track {
  background: transparent;
}

.session-news-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 25px;
}

.session-news-update {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.session-news-date {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

.session-news-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.session-news-item-icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  background: var(--glass);
  border: 1px solid var(--glass-border);
}

.session-news-item-icon i {
  font-size: 12px;
  color: var(--brand);
}

.session-news-item-body {
  min-width: 0;
}

.session-news-item-title {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.4;
}

.session-news-item-desc {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.5;
  margin-top: 2px;
}

.remember-me-row {
  margin-top: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.remember-me-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text-secondary);
  cursor: pointer;
  user-select: none;
}

.remember-me-checkbox {
  display: none;
}

.remember-me-checkmark {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  border: 1px solid var(--glass-border);
  background: var(--glass);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
  flex-shrink: 0;
}

.remember-me-checkbox:checked + .remember-me-checkmark {
  background: var(--brand);
  border-color: var(--brand);
}

.remember-me-checkbox:checked + .remember-me-checkmark::after {
  content: "";
  width: 5px;
  height: 9px;
  border: solid var(--text-on-brand);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
  margin-top: -2px;
}

.action-button {
  transition:
    background-color 0.2s,
    color 0.2s,
    opacity 0.15s ease,
    transform 0.15s ease;
}

.action-button.transitioning-out {
  opacity: 0;
  transform: translateY(-8px);
}

.action-button.transitioning-in {
  opacity: 1;
  transform: translateY(0);
}

.session-status-widget {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.session-status-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: 20px;
  padding: 6px 14px;
  backdrop-filter: blur(32px);
  cursor: pointer;
}

.session-status-toggle > i:first-child {
  color: var(--brand);
  font-size: 13px;
}

.session-status-toggle .fa-chevron-down {
  font-size: 11px;
  color: var(--text-secondary);
  transition: transform 0.2s;
}

.session-status-widget.open .session-status-toggle .fa-chevron-down {
  transform: rotate(180deg);
}

.session-status-panel {
  display: none;
  margin-top: 8px;
  width: 320px;
  max-height: 70vh;
  overflow-y: auto;
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  border-radius: 12px;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.6);
  padding: 14px 16px;
  flex-direction: column;
  gap: 10px;
}

.session-status-widget.open .session-status-panel {
  display: flex;
}

.status-info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.status-info-label {
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 500;
}

.status-info-value {
  font-size: 12px;
  color: var(--text-primary);
  font-weight: 600;
  max-width: 60%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.status-divider {
  height: 1px;
  background: var(--glass-border);
  margin: 2px 0;
}

.status-section-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.online-users-count {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--brand);
  font-weight: 600;
}

.online-users-count i {
  font-size: 13px;
  color: var(--brand);
}

.online-users-count span {
  font-weight: 600;
}

.session-live-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
}

.session-live-toggle i {
  color: var(--brand);
  font-size: 13px;
}

.session-support-btn,
.session-github-btn,
.session-discord-btn {
  position: absolute;
  top: 20px;
  width: 36px;
  height: 36px;
  border-radius: 25px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  opacity: 0.7;
  transition:
    opacity 0.2s,
    background 0.2s,
    color 0.2s,
    border-color 0.2s,
    transform 0.2s;
  pointer-events: auto;
  backdrop-filter: blur(32px);
  z-index: 11;
}

.session-support-btn:hover,
.session-github-btn:hover,
.session-discord-btn:hover {
  opacity: 1;
  background: var(--glass-hover);
  color: var(--brand);
  border-color: var(--brand);
  transform: scale(1.08);
}

.session-support-btn {
  left: 20px;
}

.session-github-btn {
  left: 64px;
}

.session-discord-btn {
  left: 108px;
}

.session-electron-banner {
  position: fixed;
  top: 50%;
  left: 32px;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: 220px;
  text-align: center;
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  padding: 16px 20px;
  border-radius: 12px;
  font-size: 13px;
  color: var(--text-secondary);
  z-index: 10;
}

.session-electron-banner > i {
  color: var(--brand);
  font-size: 24px;
}

.session-electron-banner span {
  line-height: 1.4;
}

.session-electron-banner strong {
  color: var(--text-primary);
}

.electron-banner-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  margin-top: 2px;
}

.electron-download-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-primary);
  text-decoration: none;
  font-weight: 500;
  padding: 9px 22px;
  border-radius: 10px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  font-size: 13px;
  cursor: pointer;
  user-select: none;
}

.electron-download-link:hover {
  background: var(--glass-hover);
}

.electron-download-link i {
  font-size: 13px;
}

.electron-releases-link {
  color: var(--text-muted);
  font-size: 11px;
  text-decoration: none;
  transition: color 0.15s;
}

.electron-releases-link:hover {
  color: var(--text-secondary);
  text-decoration: underline;
}

.session-electron-banner__close {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 25px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
}

.session-electron-banner__close:hover {
  background: var(--glass-hover);
  color: var(--text-primary);
}

.session-settings-btn {
  position: fixed;
  bottom: 32px;
  right: 32px;
  width: 44px;
  height: 44px;
  border-radius: 25px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  z-index: 20;
  transition:
    background-color 0.2s,
    color 0.2s,
    border-color 0.2s,
    transform 0.2s;
  backdrop-filter: blur(32px);
}

.session-settings-btn:hover {
  background: var(--glass-hover);
  color: var(--brand);
  border-color: var(--brand);
  transform: scale(1.08);
}

.session-settings-modal {
  position: fixed;
  inset: 0;
  z-index: 9999999;
  display: none;
  align-items: center;
  justify-content: center;
  background: transparent;
}

.session-settings-modal.open {
  display: flex;
}

.session-settings-content {
  max-width: 640px;
  width: 94%;
  max-height: 88vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.session-settings-content .modal-body {
  overflow-y: auto;
}

.session-settings-content .settings-card {
  margin-bottom: var(--spacing-md);
}

.session-settings-content .settings-card:last-child {
  margin-bottom: 0;
}

.boot-anim-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.boot-anim-tile {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
  padding: 10px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: 12px;
  color: var(--text-primary);
  font-size: 13px;
  cursor: pointer;
  overflow: hidden;
  transition:
    border-color 0.15s ease,
    background 0.15s ease,
    transform 0.15s ease;
}

.boot-mini-stage {
  position: relative;
  height: 110px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 8px;
  background: var(--bg-base);
  pointer-events: none;
}

.boot-mini-stage .boot-logo-wrap {
  gap: 6px;
  transform: scale(0.9);
}

.boot-mini-stage .boot-logo {
  width: 44px;
  height: 44px;
}

.boot-mini-stage .boot-glitch {
  width: 44px;
  height: 44px;
}

.boot-mini-stage .boot-letter {
  font-size: 16px;
  letter-spacing: 2px;
}

.boot-mini-stage .boot-version {
  font-size: 10px;
}

.boot-mini-stage .boot-ring {
  width: 70px;
  height: 70px;
}

.boot-mini-stage .boot-aurora {
  width: 160px;
  height: 160px;
}

.boot-mini-stage .boot-ember-holder {
  transform: scale(0.6);
}

.boot-mini-stage .boot-pixel-grid {
  inset: 20%;
}

.boot-mini-stage .boot-light-beam {
  position: absolute;
  width: 30px;
  height: 100%;
}

.boot-mini-random {
  font-size: 28px;
  color: var(--text-secondary);
}

.boot-anim-tile:hover {
  background: var(--glass-hover);
  transform: translateY(-1px);
}

.boot-anim-tile.active {
  border-color: var(--brand);
  box-shadow: 0 0 16px var(--brand-glow);
}

.boot-anim-name {
  font-weight: 700;
}

.boot-anim-hint {
  font-size: 11px;
  color: var(--text-secondary);
}

@media (max-width: 560px) {
  .boot-anim-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.status-block {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.status-block[hidden] {
  display: none;
}

.session-features-link {
  position: fixed;
  bottom: 14px;
  left: 50%;
  transform: translateX(-50%);
  color: rgba(255, 255, 255, 0.35);
  font-size: 12px;
  text-decoration: none;
  transition: color 0.15s;
  z-index: 10;
}

.session-features-link:hover {
  color: rgba(255, 255, 255, 0.7);
}

.login-tip {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: min(420px, calc(100vw - 40px));
  max-width: 420px;
  min-height: 52px;
  box-sizing: border-box;
  padding: 8px 14px;
  font-size: 12px;
  color: var(--text-secondary);
  opacity: 0.85;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  backdrop-filter: blur(32px);
  text-align: center;
  overflow: hidden;
  contain: layout paint;
  transition: opacity 0.15s ease;
  animation: tipMount 0.4s ease-out both;
}

.login-tip i {
  flex-shrink: 0;
  color: var(--brand);
  font-size: 12px;
  animation: tipBulbGlow 2.4s ease-in-out infinite;
}

.login-tip-close {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  padding: 0;
  background: transparent;
  border: none;
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 10px;
  cursor: pointer;
  opacity: 0;
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}

.login-tip-close i {
  animation: none;
  font-size: 10px;
}

.login-tip:hover .login-tip-close,
.login-tip-close:focus-visible {
  opacity: 0.85;
}

.login-tip-close:hover {
  background: var(--glass);
  opacity: 1;
}

.login-tip-hidden {
  display: none;
}

.login-tip-text {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: calc(2 * 1.45em);
  line-height: 1.45;
  text-align: center;
  text-wrap: balance;
  overflow: hidden;
  user-select: text;
  -webkit-user-select: text;
  cursor: text;
}

.login-tip-link {
  color: var(--brand);
  text-decoration: underline;
  cursor: pointer;
}

.login-tip-enter {
  animation: tipSwapIn 0.35s ease-out both;
}

.login-tip-fade {
  opacity: 0;
}

@keyframes tipMount {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 0.85;
    transform: translateY(0);
  }
}

@keyframes tipSwapIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes tipBulbGlow {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.65;
    transform: scale(1.15);
  }
}

html[data-performance="performance"] .login-tip,
html[data-performance="performance"] .login-tip i,
html[data-performance="performance"] .login-tip-text {
  animation: none;
}

html[data-theme="light"] .login-tip {
  background: #fff;
  border-color: #f0f0f0;
  color: #666;
}

html[data-theme="light"] .login-tip i {
  color: #111;
}
#yukiOS-settings {
