  flex-direction: column;
  border-right: 1px solid var(--glass-border);
  padding: 16px 12px 0 0;
}

.accounts-resizer {
  width: 4px;
  cursor: col-resize;
  background: transparent;
  flex-shrink: 0;
  margin-left: -2px;
  margin-right: -2px;
  z-index: 5;
  transition: background 0.12s;
  align-self: stretch;
}

.accounts-resizer:hover,
.accounts-resizer.active {
  background: color-mix(in oklch, var(--brand) 30%, transparent);
}

.accounts-sidebar-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 10px;
}

.accounts-user-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.accounts-empty {
  text-align: center;
  padding: 24px;
  color: var(--text-secondary);
  font-size: 14px;
}

.accounts-user-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border-radius: 8px;
  background: var(--surface-1);
  border: 1px solid var(--glass-border);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.accounts-user-item:hover {
  background: var(--glass);
}

.accounts-user-item.selected {
  background: var(--brand-dim);
  border-color: var(--brand);
}

.accounts-user-item.current {
  border-color: var(--brand);
}

.accounts-user-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid var(--glass-border);
  flex-shrink: 0;
}

.accounts-user-item.selected .accounts-user-avatar {
  border-color: var(--brand);
}

.accounts-user-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.accounts-user-info {
  flex: 1;
  min-width: 0;
}

.accounts-user-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.accounts-user-meta {
  font-size: 12px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 4px;
}

.accounts-user-meta i {
  color: var(--brand);
  font-size: 11px;
}

.accounts-user-cloud {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 6px;
  border-radius: 25px;
  background: var(--brand-dim);
  border: 1px solid var(--brand);
  color: var(--brand);
  font-size: 11px;
  font-weight: 600;
}

.accounts-user-local {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 6px;
  border-radius: 25px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 600;
}

.accounts-user-now {
  color: var(--brand);
  font-weight: 600;
}

.accounts-user-last {
  color: var(--text-secondary);
}

.accounts-detail {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 16px 0 0 12px;
  min-height: 0;
}

.accounts-detail-body {
  flex: 1;
  display: flex;
  gap: 20px;
  align-items: flex-start;
  min-height: 0;
}

.accounts-detail-avatar-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.accounts-detail-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  overflow: hidden;
  border: 3px solid var(--brand);
  flex-shrink: 0;
}

.accounts-detail-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.accounts-detail-fields {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.accounts-detail-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.accounts-detail-field label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 6px;
}

.accounts-detail-field input[type="text"] {
  padding: 10px 12px;
  border-radius: 6px;
  border: 1px solid var(--glass-border);
