}

.accounts-detail-footer {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  padding-top: 12px;
}

.accounts-detail-actions-left {
  display: flex;
  gap: 8px;
  margin-right: auto;
}

.accounts-detail-actions-right {
  display: flex;
  gap: 8px;
}

.accounts-status {
  text-align: center;
  font-size: 12px;
  color: var(--brand);
  opacity: 0;
  transition: opacity 0.3s;
  height: 14px;
  margin-top: 4px;
}

html[data-theme-mode="light"] .accounts-user-item {
  background: #f5f5f5;
  border-color: rgba(0, 0, 0, 0.1);
}

html[data-theme-mode="light"] .accounts-user-item:hover {
  background: #eaeaea;
}

html[data-theme-mode="light"] .accounts-user-item.selected {
  background: var(--brand-dim);
}

html[data-theme-mode="light"] .accounts-detail-field input[type="text"] {
  background: #f5f5f5;
  border-color: rgba(0, 0, 0, 0.12);
  color: #111;
}

/* System Diagnostics / Hardware Info */
.sysinfo-list {
  display: flex;
  flex-direction: column;
}

.sysinfo-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.03);
  transition: background var(--transition-fast);
}

.sysinfo-row:last-child {
  border-bottom: none;
}

.sysinfo-row:hover {
  background: rgba(255, 255, 255, 0.02);
}

.sysinfo-lbl {
  font-size: 14px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.85);
  white-space: nowrap;
  flex-shrink: 0;
}

.sysinfo-val {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.6);
  text-align: right;
  word-break: break-all;
  max-width: 60%;
}

.sysinfo-mono {
  font-family: "JetBrains Mono", "Cascadia Code", "Fira Code", monospace;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.5);
  line-height: 1.5;
  max-width: 65%;
  word-break: break-word;
}

html[data-theme-mode="light"] .sysinfo-lbl {
  color: var(--text-primary) !important;
}

html[data-theme-mode="light"] .sysinfo-val {
  color: var(--text-secondary) !important;
}

html[data-theme-mode="light"] .sysinfo-mono {
  color: var(--text-secondary) !important;
}

html[data-theme-mode="light"] .sysinfo-row:hover {
  background: var(--surface-hover) !important;
}

html[data-theme-mode="light"] .sysinfo-row {
  border-bottom: 1px solid var(--glass-border) !important;
}

.easing-preview {
  width: 100%;
  height: 24px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.04);
  overflow: hidden;
  padding: 0 4px;
}

.easing-preview-track {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  position: relative;
}

.easing-preview-ball {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--brand, #a78bfa);
  position: absolute;
  left: 0;
}

.easing-preview-ball.easing-preview-anim {
  animation: easing-bounce 1.2s var(--easing, ease-out) infinite alternate;
}

@keyframes easing-bounce {
  from {
    left: 0;
  }
  to {
    left: calc(100% - 12px);
  }
}

.easing-select {
  width: 100%;
}

