  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes startMenuOut {
  from {
    opacity: 1;
    transform: translateY(0);
  }

  to {
    opacity: 0;
    transform: translateY(20px);
  }
}

.start-menu {
  position: absolute;
  z-index: 10001;
  animation: startMenuIn 250ms cubic-bezier(0.22, 1, 0.36, 1) both;
