  font-size: 12px;
}

.steam-overview-avatar-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.steam-overview-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--glass-border);
  flex-shrink: 0;
}

.steam-overview-avatar-strips {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 16px;
}

