  margin: 0 0 10px;
  font-size: 12px;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.steam-overview-ach-bar {
  height: 4px;
  background: var(--glass);
  border-radius: 2px;
  margin-top: 6px;
  overflow: hidden;
}

.steam-overview-ach-fill {
  display: block;
  height: 100%;
