.wallpaper-enter {
  animation: wallpaper-enter 0.7s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

@keyframes wallpaper-enter {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.06);
  }
  100% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}
.context-menu-glass {
  background: rgba(20, 20, 20, 0.45);
  backdrop-filter: blur(32px);
  -webkit-backdrop-filter: blur(32px);
  border: 1px solid var(--glass-border);
  border-radius: var(--r);
  box-shadow:
    0 10px 30px rgba(0, 0, 0, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  font-size: 12.5px;
  color: var(--text-primary);
  overflow: hidden;
  animation: cmFadeIn 120ms ease-out both;
  outline: none;
}

.context-menu-item.has-submenu {
  display: block;
  padding: 0;
  background: none;
  border-radius: 0;
}

.context-menu-item.has-submenu > div {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border-radius: var(--r-sm);
  transition:
    background 0.12s ease,
    transform 0.05s ease;
}

.context-menu-item.has-submenu > div:hover {
  background: var(--glass-hover);
  color: var(--text-primary);
}

.context-menu-item.has-submenu > div:active {
  transform: scale(0.97);
  background: var(--glass);
}

.submenu-arrow {
  margin-left: auto;
  font-size: 10px;
  opacity: 0.5;
}

.context-menu-item.has-submenu .context-menu,
.context-menu.context-menu-glass {
  min-width: 140px;
  padding: 5px;
}

.context-menu-glass.closing {
  animation: cmFadeOut 120ms ease-in both;
  pointer-events: none;
}

.context-menu-glass > .cm-focused,
.context-menu > .cm-focused {
  background: var(--glass-hover) !important;
  color: var(--text-primary);
  border-radius: var(--r-sm);
  outline: none;
}

@keyframes cmFadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes cmFadeOut {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(4px);
  }
}
