@keyframes ovTileGlide {
  from {
    opacity: 0;
    transform: translateX(var(--glide-x)) scale(0.84);
    filter: blur(6px);
  }
  60% {
    filter: blur(0px);
  }
  to {
    opacity: 1;
    transform: translateX(0) scale(1);
    filter: blur(0px);
  }
}

@keyframes ovWsEnter {
  from {
    transform: translateY(-100%);
  }
  to {
    transform: translateY(0);
  }
}

