.widget-battery-container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100%;
}

.battery {
  position: relative;
  width: 130px;
  height: 70px;

  border: 4px solid rgba(255, 255, 255, 0.9);
  border-radius: 12px;
  overflow: hidden;
}

.battery::after {
  content: "";
  position: absolute;
  right: -10px;
  top: 22%;
  width: 8px;
  height: 56%;
  background: rgba(255, 255, 255, 0.9);
  border-radius: 3px;
}

.battery-fill {
  position: absolute;
  left: 0;
  top: 0;

  width: 0%;
  height: 100%;

  background: #22c55e;
  transition:
    width 0.5s ease,
    background 0.4s ease;
}

.battery > .battery-percent {
  position: absolute;
  inset: 0;

  display: flex;
  justify-content: center;
  align-items: center;

  font-size: 28px;
  font-weight: 700;
  color: white;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);

  z-index: 2;
  user-select: none;
}

