  background: var(--bg-secondary);
  backdrop-filter: blur(32px) saturate(1.5);
  border: 1px solid var(--glass-border);
  box-shadow:
    0 24px 64px var(--shadow-color),
    0 0 0 1px rgba(255, 255, 255, 0.05) inset;
  border-radius: 0px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.explorer-container {
  display: flex;
  flex: 1;
  min-height: 0;
  color: var(--text-primary);
  overflow: hidden;
}

.explorer-nav {
  height: 38px;
  background: var(--glass);
  backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--glass-border);
  display: flex;
  align-items: center;
  padding: 0 1.1em;
  gap: 10px;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--text-secondary);
  position: relative;
}

.explorer-nav::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 1.1em;
  right: 1.1em;
  height: 1px;
  background: linear-gradient(
    to right,
    transparent,
    var(--brand-dim) 40%,
    var(--brand-dim) 60%,
    transparent
  );
}

.explorer-nav button,
.back-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 26px;
  color: var(--text-secondary);
  border-radius: var(--r-sm);
  font-size: 12px;
  cursor: pointer;
  transition:
    background var(--transition-fast),
    color var(--transition-fast),
    box-shadow var(--transition-fast);
}

.explorer-nav button:hover,
.back-btn:hover {
  background: var(--glass-hover);
  color: var(--text-primary);
  box-shadow:
    var(--shadow-sm),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.explorer-search-input {
  margin-left: auto;
  padding: 4px 36px 4px 10px;
  border-radius: 5px;
  border: 1px solid var(--glass-border);
  background: transparent;
  color: var(--text-primary);
  font-size: 12px;
  outline: none;
  font-family: inherit;
  width: 160px;
}

.explorer-path-wrap {
  position: relative;
  flex: 1;
  display: flex;
  min-width: 0;
}

.explorer-path-wrap .explorer-win-path {
  flex: 1;
  min-width: 0;
  padding-right: 36px;
}

.explorer-reload-icon {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 12px;
  color: var(--text-secondary);
  opacity: 0.5;
  cursor: pointer;
  transition: opacity var(--transition-fast);
}

.explorer-reload-icon:hover {
  opacity: 1;
  color: var(--brand);
}

.explorer-search-input::placeholder {
  color: var(--text-secondary);
  opacity: 0.6;
}

.explorer-search-wrap {
  position: relative;
  margin-left: auto;
}

.explorer-search-icon {
  position: absolute;
