  padding: 32px 36px;
  min-width: 440px;
  max-width: 540px;
  box-shadow: var(--shadow-lg);
  color: var(--text-primary);
}

.overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 99999;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition-fast);
}

.overlay--active {
  background: var(--brand-dim);
  border: 2.5px dashed var(--brand);
  box-sizing: border-box;
}

.overlay__label {
  background: var(--bg-secondary);
  color: var(--brand);
  font-size: 15px;
  padding: 10px 22px;
  border-radius: 10px;
  pointer-events: none;
}

.explorer-trash-view {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 0;
  align-content: flex-start;
}

.explorer-trash-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  background: var(--glass);
  border-bottom: 1px solid var(--glass-border);
  flex-shrink: 0;
  width: 100%;
  box-sizing: border-box;
  gap: 16px;
}

.explorer-trash-banner-left {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  color: var(--text-primary);
}

.explorer-trash-banner-actions {
  display: flex;
  gap: 8px;
}

.explorer-trash-action-btn {
  background: var(--glass);
  border: 1px solid var(--glass-border);
  color: var(--text-secondary);
  border-radius: 6px;
  padding: 6px 14px;
  font-size: 11.5px;
  cursor: pointer;
  font-family: inherit;
  display: flex;
  align-items: center;
  gap: 6px;
  transition:
    background var(--transition-fast),
    color var(--transition-fast);
  white-space: nowrap;
}

.explorer-trash-action-btn:hover:not(:disabled) {
  background: var(--glass-hover);
  color: var(--text-primary);
}

.explorer-trash-action-btn:disabled {
  opacity: 0.4;
  cursor: default;
}

.explorer-trash-action-btn.trash-empty-all:hover:not(:disabled) {
  color: var(--error);
  border-color: var(--error);
}

.explorer-trash-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  width: 100%;
  box-sizing: border-box;
}

.conflict-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.conflict-icon {
  color: var(--brand);
  font-size: 18px;
}

.conflict-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.conflict-message {
  font-size: 12.5px;
  color: var(--text-secondary);
  margin-bottom: 18px;
  line-height: var(--lh-body);
  user-select: text;
  -webkit-user-select: text;
  cursor: text;
}

.conflict-file {
  color: var(--brand);
  font-weight: 500;
  user-select: text;
  -webkit-user-select: text;
  cursor: text;
}

.conflict-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 18px;
}

.conflict-btn {
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: 7px;
  padding: 9px 14px;
  cursor: pointer;
  font-size: 12.5px;
  text-align: left;
  transition: background var(--transition-fast);
}

.conflict-btn-icon {
  width: 16px;
  margin-right: 8px;
}

.conflict-btn-replace {
  color: var(--error);
}

.conflict-btn-keep {
  color: var(--brand);
}

.conflict-btn-skip {
  color: var(--text-secondary);
}

.conflict-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 12px;
  color: var(--text-secondary);
  user-select: none;
}

.conflict-footer input {
  accent-color: var(--brand);
  width: 13px;
  height: 13px;
  cursor: pointer;
}

.fd-dialog {
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  border-radius: 14px;
  box-shadow: var(--shadow-depth);
  padding: 28px 32px 24px;
  min-width: 440px;
  max-width: 540px;
  width: 92%;
  animation: fdDialogIn 0.15s ease;
  color: var(--text-primary);
}

.fd-dialog-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 18px;
  color: var(--text-primary);
}

.fd-dialog-label {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 8px;
  line-height: 1.5;
  user-select: text;
  -webkit-user-select: text;
  cursor: text;
}

.fd-dialog-input {
  width: 100%;
  box-sizing: border-box;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: 8px;
  color: var(--text-primary);
  font-size: 14px;
  padding: 11px 14px;
  outline: none;
  transition: border-color var(--transition-fast);
}

.fd-dialog-input:focus {
  border-color: var(--brand);
}

.fd-dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 24px;
}

.fd-btn {
  font-size: 14px;
  cursor: pointer;
  border-radius: 8px;
  padding: 10px 22px;
  border: none;
  transition:
    background 0.12s,
    opacity 0.12s;
}

.fd-btn-cancel {
  background: var(--glass);
  color: var(--text-secondary);
}

.fd-btn-cancel:hover {
  background: var(--glass-hover);
  color: var(--text-primary);
}

.fd-btn-confirm {
  background: var(--brand);
  color: var(--text-primary);
}

.fd-btn-confirm:hover {
  background: var(--brand-hover);
}

.fd-btn-confirm:disabled {
  opacity: 0.4;
  cursor: default;
}

.fd-btn-danger {
  background: var(--error);
  color: var(--text-primary);
}

.fd-btn-danger:hover {
  background: var(--error-bg);
  color: var(--error);
}

.fd-dialog-error {
  display: none;
  font-size: 13px;
  color: var(--error);
  margin-top: 8px;
  user-select: text;
  -webkit-user-select: text;
  cursor: text;
}

.fd-dialog-select {
  margin-top: 10px;
  background: var(--bg-elev-1);
  color: var(--text-primary);
  border: 1px solid var(--glass-border);
  padding: 10px 12px;
  border-radius: 8px;
  font-size: 14px;
}

.props-row {
  margin: 2px 0;
}

.desktop-icon__fallback {
  font-size: 48px;
  pointer-events: none;
}

html[data-theme-mode="light"] .explorer-main {
  background: var(--bg-primary);
}

html[data-theme-mode="light"] .explorer-sidebar {
  background: var(--bg-secondary);
  border-right: 1px solid var(--glass-border);
}

html[data-theme-mode="light"] .explorer-sidebar .nav-item {
  color: var(--text-secondary);
}

html[data-theme-mode="light"] .explorer-sidebar .nav-item:hover {
  background: var(--brand-dim);
  color: var(--text-primary);
}

html[data-theme-mode="light"] .file-item span,
html[data-theme-mode="light"] .explorer-trash-view {
  background: var(--bg-primary);
}

html[data-theme-mode="light"] .explorer-trash-banner {
  background: var(--bg-secondary);
}

html[data-theme-mode="light"] .explorer-win-path {
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  color: var(--text-primary);
}

html[data-theme-mode="light"] .explorer-win-path:focus {
  border-color: var(--brand);
  outline: 2px solid var(--brand-dim);
}

.explorer-disk-view {
  display: flex;
  flex-direction: column;
  padding: 24px 28px;
  gap: 2px;
  overflow: auto;
  height: 100%;
}

.disk-section {
  display: flex;
  flex-direction: column;
}

.disk-section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  cursor: pointer;
  user-select: none;
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
  border-bottom: 1px solid var(--glass-border);
  margin-bottom: 8px;
}

.disk-section-header:hover {
  color: var(--brand);
}

.disk-chevron {
  width: 10px;
  height: 10px;
  transition: transform var(--transition-fast);
  flex-shrink: 0;
  color: var(--text-muted);
}

.disk-section.collapsed .disk-chevron {
  transform: rotate(-90deg);
}

.disk-section.collapsed .disk-section-body {
  display: none;
}

.disk-section-body {
  display: flex;
  flex-direction: column;
  padding-bottom: 12px;
}

.disk-folder-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.disk-folder-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: 80px;
  padding: 12px 8px 8px;
  border-radius: 8px;
  cursor: pointer;
  transition: background var(--transition-fast);
  color: var(--text-secondary);
}

.disk-folder-item:hover {
  background: var(--glass-hover);
  color: var(--text-primary);
}

.disk-folder-item img {
  width: 32px;
  height: 32px;
  object-fit: contain;
  flex-shrink: 0;
}

.disk-folder-item span {
  font-size: 11px;
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
  white-space: nowrap;
}

.disk-drive-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.explorer-disk-card {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 10px 12px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: 8px;
  transition: background var(--transition-fast);
  cursor: pointer;
}

.explorer-disk-card:hover {
  background: var(--glass-hover);
}

.explorer-disk-card-icon {
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.explorer-disk-card-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.explorer-disk-card-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.explorer-disk-card-info {
  font-size: 11px;
  color: var(--text-secondary);
  margin-bottom: 4px;
}

.explorer-disk-progress {
  width: 100%;
  height: 8px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 4px;
  overflow: hidden;
}

.explorer-disk-progress-fill {
  height: 100%;
  border-radius: 4px;
  background: #26a0da;
  transition: width 0.3s ease;
  min-width: 0;
}

.explorer-container {
  position: relative;
}

.explorer-tab-bar {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 4px;
  padding: 6px 8px 0;
  background: var(--glass);
  border-bottom: 1px solid var(--glass-border);
  overflow-x: auto;
  overflow-y: hidden;
  flex-shrink: 0;
  scrollbar-width: thin;
}

.explorer-tab-bar > .explorer-tab {
  position: relative;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  min-width: 0;
  max-width: 180px;
  padding: 6px 10px;
  font-size: 13px;
  color: var(--text-muted);
  background: color-mix(in srgb, var(--brand) 6%, transparent);
  border: 1px solid transparent;
  border-bottom: none;
  border-radius: 8px 8px 0 0;
  cursor: pointer;
  touch-action: none;
  flex-shrink: 0;
  margin-bottom: 0;
  transition:
    background 0.15s,
    color 0.15s,
    border-color 0.15s;
}

.explorer-tab-bar > .explorer-tab:hover {
  background: var(--glass-hover);
  color: var(--text-primary);
  transform: none;
}

.explorer-tab-bar > .explorer-tab.active {
  background: var(--bg-secondary);
  color: var(--text-primary);
  border-color: var(--glass-border);
  border-bottom-color: var(--bg-secondary);
  border-radius: 8px 8px 0 0;
  margin-bottom: -1px;
  padding-bottom: 7px;
}

.explorer-tab-bar > .explorer-tab > .explorer-tab-icon {
  width: 14px;
  height: 14px;
  font-size: 14px;
  line-height: 14px;
  text-align: center;
  flex-shrink: 0;
  opacity: 0.55;
  transition:
    opacity 0.15s,
    color 0.15s;
}

.explorer-tab-bar > .explorer-tab:hover > .explorer-tab-icon {
  opacity: 0.85;
}

.explorer-tab-bar > .explorer-tab.active > .explorer-tab-icon {
  opacity: 1;
  color: var(--brand);
}

.explorer-tab-bar > .explorer-tab > .explorer-tab-label {
  flex: 1;
  min-width: 0;
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.explorer-tab-bar > .explorer-tab > .explorer-tab-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 0;
  height: 18px;
  margin: 0;
  margin-right: -4px;
  padding: 0;
  font-size: 12px;
  line-height: 1;
  overflow: hidden;
  opacity: 0;
  border-radius: 6px;
  cursor: pointer;
  flex-shrink: 0;
  transition:
    opacity 0.15s,
    color 0.15s,
    background 0.15s,
    width 0.15s;
}

.explorer-tab-bar > .explorer-tab:hover > .explorer-tab-close,
.explorer-tab-bar > .explorer-tab.active > .explorer-tab-close {
  width: 18px;
  margin-right: 0;
  opacity: 0.65;
}

.explorer-tab-bar > .explorer-tab > .explorer-tab-close:hover {
  opacity: 1;
  color: var(--error);
  background: var(--error-bg);
}

.explorer-tab-bar > button.explorer-tab-new {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  margin-bottom: 2px;
  margin-left: 2px;
  color: var(--text-secondary);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 50%;
  font-size: 12px;
  cursor: pointer;
  flex-shrink: 0;
  align-self: center;
  transition:
    background 0.15s,
    color 0.15s,
    border-color 0.15s;
}

.explorer-tab-bar > button.explorer-tab-new:hover {
  background: color-mix(in srgb, var(--brand) 14%, transparent);
  color: var(--brand);
  border-color: color-mix(in srgb, var(--brand) 40%, transparent);
  transform: none;
}

.explorer-split-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 26px;
  color: var(--text-secondary);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px;
  font-size: 12px;
  cursor: pointer;
  flex-shrink: 0;
  transition:
    background 0.15s,
    color 0.15s,
    border-color 0.15s,
    box-shadow 0.15s;
}

.explorer-split-btn:hover {
  background: var(--glass-hover);
  color: var(--text-primary);
  border-color: var(--glass-border);
}

.explorer-split-btn.active {
  opacity: 1;
  color: var(--brand);
  background: color-mix(in srgb, var(--brand) 14%, transparent);
  border-color: color-mix(in srgb, var(--brand) 40%, transparent);
  box-shadow: 0 0 10px color-mix(in srgb, var(--brand) 25%, transparent);
}

.explorer-container > .explorer-main {
  flex: 1;
  min-width: 0;
}

.explorer-container.split-on .explorer-main {
  flex: 1;
  min-width: 0;
}

.explorer-split-divider {
  flex: none;
  width: 7px;
  min-width: 7px;
  background: transparent;
  cursor: ew-resize;
  position: relative;
  align-self: stretch;
  border: none;
  padding: 0;
}

.explorer-split-divider::after {
  content: "";
  position: absolute;
  top: 14px;
  bottom: 14px;
  left: 50%;
  width: 3px;
  border-radius: 3px;
  transform: translateX(-50%);
  background: var(--glass-border);
  transition:
    background 0.15s,
    box-shadow 0.15s;
}

.explorer-split-divider:hover::after {
  background: color-mix(in srgb, var(--brand) 70%, transparent);
  box-shadow: 0 0 10px color-mix(in srgb, var(--brand) 45%, transparent);
}

.explorer-container > .explorer-split-pane {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  background: var(--bg-secondary);
  border-left: 1px solid var(--glass-border);
}

.explorer-split-pane > .explorer-split-header {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 34px;
  padding: 4px 8px;
  background: var(--glass);
  border-bottom: 1px solid var(--glass-border);
  font-size: 12px;
  color: var(--text-secondary);
  flex-shrink: 0;
}

.explorer-split-header > .explorer-split-back,
.explorer-split-header > .explorer-split-up {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 26px;
  font-size: 12px;
  color: var(--text-secondary);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  flex-shrink: 0;
  transition:
    background 0.15s,
    color 0.15s,
    border-color 0.15s;
}

.explorer-split-header > .explorer-split-back:hover,
.explorer-split-header > .explorer-split-up:hover {
  background: var(--glass-hover);
  color: var(--text-primary);
  border-color: var(--glass-border);
}

.explorer-split-header > span.explorer-split-path {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--text-secondary);
}

.explorer-dock-zone {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
  z-index: 60;
  opacity: 0;
  pointer-events: none;
  background: color-mix(in srgb, var(--brand) 14%, transparent);
  border: 1px dashed color-mix(in srgb, var(--brand) 45%, transparent);
  transition:
    opacity 0.15s,
    background 0.15s,
    border-color 0.15s;
}

.explorer-dock-zone[id$="dock-left"] {
  left: 0;
  right: auto;
}

.explorer-dock-zone[id$="dock-right"] {
  right: 0;
  left: auto;
}

.explorer-window.tab-dragging .explorer-dock-zone {
  opacity: 1;
  pointer-events: auto;
}

.explorer-dock-zone.active {
  background: color-mix(in srgb, var(--brand) 28%, transparent);
  border-color: var(--brand);
  border-style: solid;
}

span.explorer-status-selected {
  user-select: text;
  -webkit-user-select: text;
  cursor: text;
  color: var(--text-secondary);
  font-size: 12px;
}

span.explorer-status-selected.selectable {
  user-select: text;
  -webkit-user-select: text;
  cursor: text;
}
