  overflow-y: auto;
  overflow-x: hidden;
}

.wx-body::-webkit-scrollbar {
  width: 4px;
}

.wx-body::-webkit-scrollbar-track {
  background: transparent;
}

.wx-body::-webkit-scrollbar-thumb {
  background: var(--glass-border);
}

.wx-main {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.wx-hero {
  background: linear-gradient(
    160deg,
    var(--surface-2) 0%,
    var(--surface-3) 100%
  );
  padding: 28px 20px 20px;
  text-align: center;
  border-bottom: 1px solid var(--glass-border);
}

.wx-location {
  font-size: 13px;
  color: var(--brand);
  letter-spacing: var(--ls-wide);
  text-transform: uppercase;
  margin-bottom: 10px;
}

.wx-icon-big {
  font-size: 56px;
  line-height: 1;
  margin-bottom: 8px;
}

.wx-temp-big {
  font-size: 52px;
  font-weight: bold;
  color: var(--text-primary);
  line-height: 1;
}

.wx-condition {
  font-size: 14px;
  color: var(--text-secondary);
  margin-top: 6px;
}

.wx-feels {
  font-size: 1em;
  color: var(--text-muted);
  margin-top: 4px;
}

.wx-stats {
