  justify-content: space-around;
  padding: 16px 10px;
  border-bottom: 1px solid var(--glass-border);
  background: var(--surface-1);
}

.wx-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.wx-stat-icon {
  font-size: 18px;
}

.wx-stat-val {
  font-size: 13px;
  font-weight: bold;
  color: var(--text-primary);
}

.wx-stat-label {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: var(--ls-wide);
}

.wx-forecast {
  padding: 1em 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.wx-forecast-day {
  display: flex;
  align-items: center;
  padding: 8px 1em;
  background: var(--surface-1);
  border: 1px solid var(--glass-border);
  gap: 10px;
}

.wx-fday {
  width: 72px;
  font-size: 1em;
  color: var(--brand);
  text-transform: uppercase;
  letter-spacing: var(--ls-wide);
