.wx-ficon {
  font-size: 20px;
  flex: 1;
  text-align: center;
}

.wx-ftemp {
  display: flex;
  gap: 8px;
  align-items: center;
}

.wx-fmax {
  font-size: 14px;
  font-weight: bold;
  color: var(--text-primary);
}

.wx-fmin {
  font-size: 1em;
  color: var(--text-muted);
}

.wx-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
