  font-size: 13px;
}

.wx-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 40px 20px;
  text-align: center;
  gap: 12px;
}

.wx-placeholder-icon {
  font-size: 64px;
  margin-bottom: 8px;
}

.wx-placeholder-title {
  font-size: 20px;
  font-weight: bold;
  color: var(--text-primary);
}

.wx-placeholder-desc {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 16px;
}

.wx-placeholder-tips {
