  background: rgba(255, 255, 255, 0.19);
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: background 0.12s;
}

.shelf-status-date {
  display: flex;
  align-items: center;
  height: 36px;
  padding: 0 6px 0 12px;
  border-radius: 25px 8px 8px 25px;
  background: rgba(255, 255, 255, 0.19);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-right: none;
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
