}

.shelf-status-ball {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.19);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
  cursor: pointer;
}

.shelf-status-ball svg {
  width: 18px;
  height: 18px;
}

.shelf-status-ball .shelf-ball-text {
  font-size: 0.85em;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.shelf-pos-left .shelf-status-date,
.shelf-pos-right .shelf-status-date {
  border-radius: 25px 25px 8px 8px;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
