}

.shelf-status-clock {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  height: 36px;
  padding: 0 8px;
  border-radius: 25px;
  cursor: pointer;
  transition: background 0.12s;
}

.shelf-status-clock:hover {
  background: rgba(255, 255, 255, 0.08);
}

.shelf-status-icons {
  display: flex;
  align-items: center;
  height: 36px;
  border-radius: 25px;
  cursor: pointer;
  color: var(--text-primary);
  font-size: 13px;
  transition: background 0.12s;
}

.shelf-status-icons:hover {
  background: rgba(255, 255, 255, 0.08);
}

.shelf-status-battery {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.shelf-status .shelf-battery-btn {
  background: transparent;
  border: none;
  color: var(--text-primary);
  height: 36px;
  padding: 0 8px;
  border-radius: 25px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 16px;
  transition: background 0.12s;
}

.shelf-status .shelf-battery-btn:hover {
  background: rgba(255, 255, 255, 0.08);
}

.shelf-status .shelf-battery-btn svg,
.shelf-status .shelf-battery-btn i {
  font-size: 16px;
}

.shelf-status .shelf-battery-btn .fa-bolt {
  color: var(--charging);
}

#chromeos-quick-settings {
  display: none;
  position: fixed;
  z-index: 10001;
  width: 400px;
  max-width: calc(100vw - 24px);
  background: color-mix(in srgb, var(--text-secondary) 82%, transparent);
  backdrop-filter: blur(32px);
  -webkit-backdrop-filter: blur(32px);
  border-radius: 20px;
  border: 1px solid #c8c8c8b3;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.35);
  padding: 16px;
  overflow: hidden;
  color: white;
  font-size: 13px;
  animation: qs-panel-in 0.18s cubic-bezier(0.2, 0, 0.3, 1);
}

#chromeos-quick-settings.closing {
  animation: qs-panel-out 0.15s ease forwards;
}

@keyframes qs-panel-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes qs-panel-out {
  to {
    opacity: 0;
    transform: scale(0.96);
  }
}

.chromeos-qs {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.chromeos-qs-main {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.chromeos-qs-wide {
  grid-column: span 2;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
  min-width: 0;
  padding: 12px 14px;
  border-radius: 18px;
  background: #c8c8c8b3;
  border: 1px solid #c8c8c8b3;
  cursor: pointer;
}

.chromeos-qs-wide:hover {
  background: #fff;
}

.chromeos-qs-wide.on {
  background: var(--brand-dim);
  border-color: var(--brand);
}

.chromeos-qs-wide.on .chromeos-qs-wide-icon {
  color: var(--brand);
}

.chromeos-qs-wide-icon {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: white;
  font-size: 15px;
}

.chromeos-qs-wide-texts {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: left;
  min-width: 0;
  flex: 1;
}

.chromeos-qs-wide-title {
  font-size: 13px;
  font-weight: 600;
  color: white;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chromeos-qs-wide-sub {
  font-size: 12px;
  color: #f9f9f9;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chromeos-qs-squares {
  grid-column: span 2;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.chromeos-qs-square {
  aspect-ratio: 1 / 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 0;
  padding: 12px;
  border-radius: 18px;
  background: #c8c8c8b3;
  border: 1px solid #c8c8c8b3;
  font-size: 11px;
  font-weight: 600;
  text-align: center;
  cursor: pointer;
}

.chromeos-qs-square i {
  font-size: 16px;
  color: #f9f9f9;
}

.chromeos-qs-square:hover {
  background: #fff;
}

.chromeos-qs-square.on {
  background: var(--brand-dim);
  border-color: var(--brand);
}

.chromeos-qs-square.on i {
  color: var(--brand);
}

.chromeos-qs-focus {
  grid-column: span 2;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 14px;
  background: #c8c8c8b3;
  border: 1px solid #c8c8c8b3;
  color: white;
  font-size: 12px;
  text-align: left;
  cursor: pointer;
}

.chromeos-qs-focus:hover {
  background: #fff;
}

.chromeos-qs-focus.on {
  background: var(--brand-dim);
  border-color: var(--brand);
}

.chromeos-qs-trayflow {
  grid-column: span 2;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chromeos-qs-trayflow:empty {
  display: none;
}

.chromeos-qs-tray {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  font-weight: 700;
  border-radius: 9px;
  background: #c8c8c8b3;
  border: 1px solid #c8c8c8b3;
  color: white;
  font-size: 11px;
  text-align: left;
  cursor: pointer;
}

.chromeos-qs-tray:hover {
  background: #fff;
}

.chromeos-qs-tray.has-notifications {
  background: var(--brand-dim);
  border-color: var(--brand);
  color: var(--brand);
}

.chromeos-qs-slider {
  grid-column: span 4;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  position: relative;
}

.chromeos-qs-slider-icon {
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: white;
  font-size: 13px;
  cursor: pointer;
  pointer-events: auto;
}

.chromeos-qs-slider.is-active .chromeos-qs-slider-icon {
  color: var(--bg-primary);
}

.chromeos-qs-slider-icon svg,
.chromeos-qs-slider-icon i {
  pointer-events: none;
}

.chromeos-qs-slider-icon::after {
  content: "";
  position: absolute;
  left: 9px;
  right: 9px;
  top: 50%;
  height: 2px;
  border-radius: 2px;
  background: var(--text-primary);
  transform: translateY(-50%) rotate(-45deg) scaleX(0);
  transform-origin: center;
  pointer-events: none;
}

.chromeos-qs-slider.is-muted .chromeos-qs-slider-icon::after {
  transform: translateY(-50%) rotate(-45deg) scaleX(1);
}

.chromeos-qs-slider .range-slider {
  flex: 1;
  min-width: 0;
  max-width: none;
  height: 28px;
}

.chromeos-qs-slider .range-slider .range-slider__track {
  height: 28px;
  border-radius: 14px;
  background: linear-gradient(
    to bottom,
    transparent calc(50% - 3.25px),
    #000 calc(50% - 3.25px),
    #000 calc(50% + 3.25px),
    transparent calc(50% + 3.25px)
  );
}

.chromeos-qs-slider.is-active .range-slider .range-slider__track {
  background: linear-gradient(
    to bottom,
    transparent calc(50% - 3.25px),
    #c8c8c8b3 calc(50% - 3.25px),
    #c8c8c8b3 calc(50% + 3.25px),
    transparent calc(50% + 3.25px)
  );
}

.chromeos-qs-slider .range-slider .range-slider__fill {
  border-radius: 14px;
