.snapcont {
  box-sizing: border-box;
  width: 260px;
  height: 130px;
  position: fixed;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: repeat(2, minmax(0, 1fr));
  gap: 8px;
  padding: 8px;
  background: var(--menu-bg);
  border: solid 1px var(--glass-border);
  border-radius: 6px;
  transform-origin: top right;
  opacity: 0;
  transform: scale(0.8);
  pointer-events: none;
  transition:
    opacity 0.1s ease-out,
    transform 0.1s ease-out;
  z-index: 10000;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
}

.snapcont.snapcont--revealed {
  opacity: 1;
  transform: scale(1);
  pointer-events: auto;
}

.snapBar {
  position: fixed;
  top: 0;
  left: 50%;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: var(--menu-bg);
  border: solid 1px var(--glass-border);
  border-top: none;
  border-radius: 0 0 6px 6px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  transform: translate(-50%, calc(-100% + 20px));
  transition: transform 0.28s cubic-bezier(0.2, 0.8, 0.3, 1);
  pointer-events: none;
  z-index: 10000;
}

.snapBar.snapBar--entering {
  transform: translate(-50%, -100%);
  transition: none;
}

.snapBar[data-hide="true"] {
  transform: translate(-50%, -100%);
  opacity: 0;
  pointer-events: none;
  transition:
    transform 0.2s cubic-bezier(0.2, 0.8, 0.3, 1),
    opacity 0.2s ease;
}

.snapBar.snapBar--revealed {
  transform: translate(-50%, 0);
  pointer-events: auto;
}

.snapPreview {
  position: fixed;
  border-radius: 6px;
  background: rgba(150, 150, 150, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.18);
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  opacity: 0;
  pointer-events: none;
  transition:
    left 0.18s cubic-bezier(0.2, 0.8, 0.3, 1),
    top 0.18s cubic-bezier(0.2, 0.8, 0.3, 1),
    width 0.18s cubic-bezier(0.2, 0.8, 0.3, 1),
    height 0.18s cubic-bezier(0.2, 0.8, 0.3, 1),
    opacity 0.15s ease-out;
  z-index: 900;
}

.snapPreview.snapPreview--visible {
  opacity: 1;
}

.snapLayouts .snapper {
  box-sizing: border-box;
  background: var(--surface-hover);
  border: solid 1px var(--glass-border);
  border-radius: 3px;
  transition: all ease-in-out 100ms;
  cursor: pointer;
}

.snapBar .snapper {
  border-radius: 6px;
}

.snapBar .snapLay {
  width: 62px;
  height: 38px;
  border-radius: 6px;
  overflow: hidden;
}

.snapLayouts .snapper:hover {
  background: var(--win11-accent);
  border: solid 1px var(--win11-accent);
}

.snapLayouts .snapLay {
  display: grid;
  grid-column-gap: 3px;
  grid-row-gap: 3px;
}

.snapLayouts .snapLay:nth-child(1) {
  grid-template-columns: auto auto;
}

.snapLayouts .snapLay:nth-child(2) {
  grid-template-columns: auto auto auto;
}

.snapLayouts .snapLay:nth-child(2) .snapper:first-child {
  grid-column-end: span 2;
}

.snapLayouts .snapLay:nth-child(3) {
  grid-template-columns: auto auto auto;
}

.snapLayouts .snapLay:nth-child(4) {
  grid-template-columns: auto auto;
  grid-template-rows: auto auto;
}

.snapLayouts .snapLay:nth-child(4) .snapper:first-child {
  grid-row: 1 / span 2;
}

.snapLayouts .snapLay:nth-child(5) {
  grid-template-columns: auto auto;
  grid-template-rows: auto auto;
  grid-column-gap: 4px;
}

.snapLayouts .snapLay:nth-child(6) {
  grid-template-columns: auto auto auto auto auto auto auto;
}

.snapLayouts .snapLay:nth-child(6) .snapper {
  grid-column-end: span 2;
}

.snapLayouts .snapLay:nth-child(6) .snapper:nth-child(2) {
  grid-column: 3 / span 3;
}

