:root {
  --tiling-bar-height: 38px;
  --tiling-bar-bg: rgba(12, 12, 20, 0.75);
  --tiling-bar-text: var(--text-primary, #eee);
  --tiling-bar-text-secondary: var(--text-secondary, rgba(255, 255, 255, 0.55));
  --tiling-bar-accent: var(--brand, #7c5cff);
  --tiling-bar-pill-bg: rgba(255, 255, 255, 0.06);
}

body.tiling-active #taskbar {
  display: none;
}

body.tiling-active #tiling-bar {
  display: flex;
}

#tiling-bar {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--tiling-bar-height);
  background: var(--tiling-bar-bg);
  backdrop-filter: blur(40px);
  -webkit-backdrop-filter: blur(40px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  z-index: 9999;
  align-items: center;
  justify-content: center;
  padding: 0 12px;
  gap: 6px;
  user-select: none;
  font-size: 13px;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.35);
}

#tiling-bar.position-bottom {
  top: auto;
  bottom: 0;
  border-bottom: none;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

#tiling-bar .tiling-bar-section {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 28px;
  padding: 0 6px;
  background: var(--tiling-bar-pill-bg);
  border-radius: 25px;
  border: 1px solid rgba(255, 255, 255, 0.04);
}

#tiling-bar .tiling-bar-left {
  flex: 0 0 auto;
}

#tiling-bar .tiling-bar-right {
  flex: 0 0 auto;
  margin-left: auto;
}

.tiling-rofi-trigger {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 25px;
  cursor: pointer;
  color: var(--tiling-bar-text-secondary);
  transition:
    background 0.1s,
    color 0.1s;
  border: none;
  background: transparent;
  font-size: 13px;
  font-family: inherit;
  flex-shrink: 0;
}

.tiling-rofi-trigger:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--tiling-bar-text);
}

.tiling-rofi-trigger i {
  font-size: 14px;
}

.tiling-ws-pills {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 0 2px;
}

.tiling-ws-pill {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 25px;
  border: none;
  background: rgba(255, 255, 255, 0.08);
  color: var(--tiling-bar-text-secondary);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s,
    transform 0.12s;
  font-family: inherit;
  line-height: 1;
}

.tiling-ws-pill:hover {
  background: rgba(255, 255, 255, 0.14);
  color: var(--tiling-bar-text);
}

.tiling-ws-pill.active {
  background: var(--tiling-bar-accent);
  color: #fff;
  transform: scale(1.05);
}

.tiling-tray-dedicated {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 26px;
  min-width: 26px;
  padding: 0 5px;
  border-radius: 25px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.04);
  cursor: default;
}

.tiling-tray-dedicated .tray-icon-btn {
  width: 24px;
  height: 24px;
  font-size: 12px;
  border-radius: 25px;
}

.tiling-tray-dedicated .tray-icon-btn img {
  width: 15px;
  height: 15px;
  object-fit: contain;
}

.tiling-tray-dedicated .tray-icon-btn i {
  font-size: 13px;
}

.tiling-tray-dedicated.power {
  padding: 0 6px;
}

.tiling-tray-dedicated.power .charging-icon {
  margin-right: 1px;
  color: #22c55e;
  animation: battery-pulse 1.5s ease-in-out infinite;
}

.tiling-tray-dedicated.power.charging {
  color: #22c55e;
}

.tiling-tray-dedicated.power.warning {
  color: #facc15;
}

.tiling-tray-dedicated.power.critical {
  color: #ef4444;
}

.tiling-tray-dedicated.power.critical i {
  animation: battery-blink 0.8s step-end infinite;
}

@keyframes battery-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

@keyframes battery-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.2;
  }
}

.tiling-tray-dedicated.audio.muted {
  color: #ef4444;
}

.tiling-tray-dedicated.audio.low {
  color: var(--tiling-bar-text-secondary);
}

.tiling-tray-dedicated.audio.high {
  color: var(--tiling-bar-text);
}

.tiling-tray-dedicated.network.disconnected {
  opacity: 0.35;
  animation: net-pulse 2s ease-in-out infinite;
}

@keyframes net-pulse {
  0%,
  100% {
    opacity: 0.35;
  }
  50% {
    opacity: 0.6;
  }
}

.tiling-tray-items {
  display: flex;
  align-items: center;
  gap: 1px;
  height: 100%;
}

.tiling-tray-items .tray-icon-btn {
  width: 26px;
  height: 26px;
  font-size: 12px;
  border-radius: 25px;
}

.tiling-tray-items .tray-icon-btn img {
  width: 16px;
  height: 16px;
