  animation: battery-blink 0.8s step-end infinite;
}

@keyframes battery-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

@keyframes battery-blink {
  0%,
  100% {
