  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 25px;
  cursor: pointer;
  color: var(--tiling-bar-text-secondary);
  transition:
    background 0.1s,
    color 0.1s;
  border: none;
  background: transparent;
  font-size: 11px;
  font-family: inherit;
  flex-shrink: 0;
}

.tiling-keybind-hint:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--tiling-bar-text);
}

.tiling-keybind-hint i {
  font-size: 13px;
}

#tiling-keybind-overlay {
  display: none;
  flex-direction: column;
  position: fixed;
  top: calc(var(--tiling-bar-height) + 8px);
  left: 50%;
  transform: translateX(-50%);
  z-index: 10000;
  background: rgba(10, 10, 20, 0.92);
  backdrop-filter: blur(50px);
  -webkit-backdrop-filter: blur(50px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 16px;
  box-shadow: 0 16px 64px rgba(0, 0, 0, 0.55);
  width: min(480px, 90vw);
  max-height: min(70vh, 520px);
  overflow: hidden;
}

#tiling-keybind-overlay.position-bottom {
  top: auto;
  bottom: calc(var(--tiling-bar-height) + 8px);
}

.tiling-kb-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  font-size: 14px;
  font-weight: 600;
  color: var(--tiling-bar-text);
}

.tiling-kb-header i {
  font-size: 16px;
  color: var(--tiling-bar-accent);
}

.tiling-kb-body {
  flex: 1;
  overflow-y: auto;
  padding: 8px 0;
}

.tiling-kb-category {
  padding: 4px 0;
}

.tiling-kb-cat-title {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 18px 4px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--tiling-bar-text-secondary);
}

.tiling-kb-cat-title i {
  font-size: 12px;
  width: 16px;
  text-align: center;
}

.tiling-kb-items {
  display: flex;
  flex-direction: column;
}

.tiling-kb-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 18px 5px 42px;
  gap: 12px;
}

.tiling-kb-row span {
  font-size: 12px;
  color: var(--tiling-bar-text);
  text-align: right;
  flex-shrink: 0;
}

.tiling-kb-row kbd {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.07);
  font-family: inherit;
  font-size: 11px;
  color: var(--tiling-bar-text);
  white-space: nowrap;
  border: 1px solid rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}

.tiling-kb-row:hover {
  background: rgba(255, 255, 255, 0.03);
}

.tiling-kb-body::-webkit-scrollbar {
  width: 4px;
}

.tiling-kb-body::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 4px;
}

.tiling-kb-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.tiling-kb-hide-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 25px;
  padding: 4px 12px;
  font-size: 11px;
  color: var(--tiling-bar-text-secondary);
  cursor: pointer;
  font-family: inherit;
  transition:
    background 0.1s,
    color 0.1s;
}

.tiling-kb-hide-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--tiling-bar-text);
}

.tiling-kb-hide-btn i {
  font-size: 12px;
}
@keyframes steam-rainbow-shift {
  to {
    background-position: 200% center;
  }
}

@keyframes steam-foil-drift {
  to {
    background-position: 200% 200%;
  }
}

@keyframes steam-sheen-pass {
  0% {
    background-position:
      -75% -25%,
      0 0,
      0 0;
  }
  50% {
    background-position:
      175% 125%,
      0 0,
      0 0;
  }
  100% {
    background-position:
      -75% -25%,
      0 0,
      0 0;
  }
}

@keyframes steam-holo-hue {
  to {
    filter: hue-rotate(360deg);
  }
}

@keyframes steam-glow-pulse {
  0%,
  100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.28);
  }
}

