.steam-social-search {
  width: 100%;
  flex-shrink: 0;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  background: var(--surface-1);
  color: var(--text-primary);
  font-size: 13px;
  outline: none;
  transition: border-color var(--transition-fast);
}

.steam-social-search:focus {
  border-color: var(--brand);
}

.steam-social-search::placeholder {
  color: var(--text-muted);
}

.steam-social-list {
  overflow-y: auto;
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  gap: 10px;
  align-content: start;
  padding-right: 2px;
}

.steam-social-row {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 18px 12px 14px;
  border-radius: 12px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  cursor: pointer;
  text-align: center;
  position: relative;
  transition:
    background var(--transition-fast),
    border-color var(--transition-fast),
    transform var(--transition-fast),
    box-shadow var(--transition-fast);
}

.steam-social-row:hover {
  background: var(--glass-hover);
  border-color: var(--brand-dim);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.35);
}

.steam-social-row:active {
  transform: translateY(0);
  box-shadow: none;
}

.steam-social-row--self {
  border-color: var(--brand-dim);
}

.steam-social-avatar-wrap {
  position: relative;
  flex-shrink: 0;
}

.steam-social-avatar {
  width: 64px;
  height: 64px;
  border-radius: 25px;
  object-fit: cover;
  display: block;
  flex-shrink: 0;
  border: 2px solid var(--surface-2);
  background: var(--surface-1);
}

.steam-social-avatar--default {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  background: var(--surface-2);
  font-size: 24px;
}

.steam-social-presence-dot {
  position: absolute;
  right: -1px;
  bottom: -1px;
  width: 15px;
  height: 15px;
  border-radius: 25px;
  border: 2px solid var(--bg-base);
  background: var(--text-muted);
  box-sizing: border-box;
}

.steam-social-presence-dot--online,
.steam-social-presence-dot--playing {
  background: var(--status-online);
}

.steam-social-presence-dot--playing {
  box-shadow: 0 0 0 2px var(--status-online-bg);
}

.steam-social-presence-dot--offline {
  background: var(--text-muted);
}

.steam-social-presence-dot--invisible {
  background: var(--border);
}

.steam-social-info {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  min-width: 0;
  width: 100%;
}

.steam-social-name {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  max-width: 100%;
  flex-wrap: wrap;
}

.steam-social-name-text {
  font-size: 13.5px;
  font-weight: 700;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.steam-social-you {
  font-size: 10px;
  padding: 1px 5px;
  border-radius: 6px;
  background: var(--brand-dim);
  color: var(--brand);
  text-transform: uppercase;
  letter-spacing: var(--ls-wide);
  flex-shrink: 0;
}

.steam-social-status {
  display: inline-flex;
  align-items: center;
  padding: 1px 8px;
  border-radius: 25px;
  background: var(--surface-1);
  font-size: 11px;
  color: var(--text-secondary);
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.steam-social-status--offline {
  color: var(--text-muted);
}

.steam-social-status--invisible {
  color: var(--brand);
}

.steam-social-status-row {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  max-width: 100%;
}

.steam-status-picker-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 5px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  border-radius: 6px;
  transition: color var(--transition-fast);
}

.steam-status-picker-btn:hover {
  color: var(--brand);
}

.steam-status-picker-btn--presence {
  margin-left: 4px;
}

.steam-social-status--online,
.steam-social-status--playing {
  color: var(--status-online);
  background: var(--status-online-bg);
  font-weight: 600;
}

.steam-social-meta {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  max-width: 100%;
  min-width: 0;
  overflow: hidden;
}

.steam-social-stat {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 25px;
  background: var(--surface-1);
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.steam-social-stat i {
  color: var(--brand);
  font-size: 10px;
}

.steam-social-stat-sep {
  color: var(--text-muted);
  font-size: 11px;
  flex-shrink: 0;
}

.steam-social-loading,
.steam-social-error {
  padding: 24px 12px;
  text-align: center;
  font-size: 13px;
  color: var(--text-secondary);
}

.steam-social-error {
  color: var(--error);
}

.steam-profile {
  max-width: 960px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.steam-profile-banner {
  height: 130px;
  border-radius: 14px;
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(120% 180% at 10% 0%, var(--brand-glow), transparent 55%),
    linear-gradient(135deg, var(--surface-2), var(--bg-base));
  border: 1px solid var(--glass-border);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.steam-profile-hero {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 20px;
  padding: 18px;
  border-radius: 12px;
  background: var(--surface-2);
  border: 1px solid var(--glass-border);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  position: relative;
  z-index: 1;
  margin-top: -48px;
}

.steam-profile-hero-left {
  display: flex;
  align-items: flex-start;
  gap: 18px;
  flex: 1;
  min-width: 0;
}

.steam-profile-frame {
  position: relative;
  width: clamp(120px, 26vw, 168px);
  aspect-ratio: 1 / 1;
  border-radius: 12px;
  padding: 6px;
  background: var(--surface-2);
  border: 1px solid rgba(255, 255, 255, 0.16);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2);
  flex-shrink: 0;
  align-self: flex-start;
}

.steam-profile-frame-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 7px;
}

.steam-profile-frame-change {
  position: absolute;
  inset: 6px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.55);
  color: #ffffff;
  border: none;
  cursor: pointer;
  font-size: 20px;
  opacity: 0;
  transition: opacity var(--transition-fast);
}

.steam-profile-frame:hover .steam-profile-frame-change {
  opacity: 1;
}

.steam-profile-frame-img--default {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 56px;
  color: var(--text-secondary);
  background: var(--surface-1);
}

.steam-profile-identity {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 8px;
  min-width: 0;
}

.steam-profile-name {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 28px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.1;
}

.steam-profile-presence {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
}

.steam-profile-presence--online {
  color: var(--brand);
}

.steam-profile-presence--invisible {
  color: var(--text-secondary);
}

.steam-profile-presence--offline {
  color: var(--text-muted);
}

.steam-profile-bio {
  font-size: 13px;
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-word;
}

.steam-profile-bio-empty {
  color: var(--text-muted);
  font-style: italic;
}

.steam-profile-bio-edit-btn {
  align-self: flex-start;
  padding: 6px 14px;
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  background: var(--surface-1);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background var(--transition-fast),
    color var(--transition-fast),
    border-color var(--transition-fast);
}

.steam-profile-bio-edit-btn:hover {
  background: var(--brand-dim);
  color: var(--brand);
  border-color: var(--brand);
}

.steam-profile-bio-editor {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.steam-profile-bio-input {
  width: 100%;
  min-height: 80px;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  background: var(--surface-1);
  color: var(--text-primary);
  font-size: 13px;
  font-family: inherit;
  resize: vertical;
  outline: none;
  transition: border-color var(--transition-fast);
}

.steam-profile-bio-input:focus {
  border-color: var(--brand);
}

.steam-profile-bio-input::placeholder {
  color: var(--text-muted);
}

.steam-profile-bio-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.steam-profile-bio-save-btn,
.steam-profile-bio-cancel-btn {
  padding: 7px 14px;
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  background: var(--surface-1);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background var(--transition-fast),
    color var(--transition-fast),
    border-color var(--transition-fast);
}

.steam-profile-bio-save-btn:hover,
.steam-profile-bio-cancel-btn:hover {
  background: var(--brand-dim);
  color: var(--brand);
  border-color: var(--brand);
}

.steam-profile-bio-error {
  font-size: 12px;
  color: var(--error);
}

.steam-profile-hero-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
  flex-shrink: 0;
}

.steam-profile-level {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.steam-profile-level-label {
  font-size: 12px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: var(--ls-wide);
}

.steam-profile-level-circle {
  width: 58px;
  height: 58px;
  border-radius: 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  font-weight: 800;
  color: var(--text-primary);
  background: var(--bg-base);
  border: 1px solid var(--glass-border);
}

.steam-profile-level-bar {
  width: 74px;
  height: 5px;
  border-radius: 3px;
  background: var(--surface-2);
  overflow: hidden;
}

.steam-profile-level-bar-fill {
  height: 100%;
  background: var(--brand);
  border-radius: 3px;
}

.steam-profile-level-xp {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: var(--ls-wide);
}

.steam-profile-featured {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 10px;
