  color: var(--text-secondary);
}

.yukios-account-meta strong {
  color: var(--text-primary);
}

.yukios-account-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.yukios-account-btn {
  padding: 8px 14px;
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  background: var(--surface-2);
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition:
    background var(--transition-fast),
    color var(--transition-fast),
    border-color var(--transition-fast);
}

.yukios-account-btn:hover {
  border-color: var(--brand);
  color: var(--brand);
}

.yukios-account-btn--primary {
  background: var(--surface-2);
  border-color: var(--brand);
  color: var(--text-on-brand);
}

.yukios-account-btn--primary:hover {
  background: var(--brand-hover);
  color: var(--text-on-brand);
}

.yukios-account-btn:disabled {
  opacity: 0.6;
  cursor: default;
}

.yukios-account-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.yukios-account-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
}

.yukios-account-label span {
  color: var(--text-muted);
  font-weight: 400;
}

.yukios-account-input {
  width: 100%;
  padding: 9px 12px;
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  background: var(--bg-base);
  color: var(--text-primary);
  font-size: 13px;
  outline: none;
  box-sizing: border-box;
  transition: border-color var(--transition-fast);
}

.yukios-account-input:focus {
  border-color: var(--brand);
}

.yukios-account-error {
  font-size: 12px;
  color: var(--error);
  line-height: 1.4;
}

.yukios-account-disclaimer {
  margin: 0;
  font-size: 11px;
  line-height: 1.5;
  color: var(--text-muted);
  padding-top: 4px;
  border-top: 1px solid var(--glass-border);
}

.steam-login-page {
  height: 100%;
  overflow-y: auto;
  padding: 6px 16px 48px;
  display: flex;
  flex-direction: column;
}

.steam-login-card {
  width: 100%;
  max-width: 420px;
  margin: 8vh auto 0;
  padding: 24px;
  border-radius: 12px;
  background: var(--surface-1);
  border: 1px solid var(--glass-border);
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.steam-login-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.steam-login-brand-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--brand);
  color: var(--text-on-brand);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex-shrink: 0;
}

.steam-login-title {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
}

.steam-login-subtitle {
  margin: 0;
  font-size: 12px;
  color: var(--text-secondary);
}

.steam-login-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.steam-login-back-btn {
  padding: 8px 14px;
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  background: var(--surface-2);
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition:
    color var(--transition-fast),
    border-color var(--transition-fast);
}

.steam-login-back-btn:hover {
  border-color: var(--brand);
  color: var(--brand);
}

.steam-profile-account-entry {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  padding: 7px 12px;
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  background: var(--surface-2);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition:
    color var(--transition-fast),
    border-color var(--transition-fast);
}

.steam-profile-account-entry:hover {
  color: var(--brand);
  border-color: var(--brand);
}

.steam-social-disabled {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 100%;
  padding: 40px 24px;
  text-align: center;
  color: var(--text-secondary);
}

.steam-social-disabled > i {
  font-size: 34px;
  color: var(--text-muted);
}

.steam-social-disabled-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
}

.steam-social-disabled-desc {
  font-size: 13px;
  line-height: 1.5;
  max-width: 320px;
}

.steam-social-friend-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 6px;
  flex-wrap: wrap;
}

.steam-friend-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border: 1px solid var(--glass-border);
  border-radius: 8px;
  background: var(--glass);
  color: var(--text-primary);
  font-size: 12px;
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.1s ease;
  backdrop-filter: blur(24px);
}

.steam-friend-btn:hover {
  border-color: var(--brand);
  background: rgba(255, 255, 255, 0.08);
  transform: translateY(-1px);
}

.steam-friend-btn--active {
  color: var(--brand);
  border-color: var(--brand-dim);
  cursor: default;
}

.steam-friend-btn--sent {
  color: var(--text-secondary);
  cursor: default;
}

.steam-friend-btn--accept {
  color: var(--brand);
}

.steam-friend-btn--decline,
.steam-friend-btn--remove {
  color: var(--text-secondary);
}

.steam-friend-btn--decline:hover,
.steam-friend-btn--remove:hover {
  color: var(--error);
  border-color: var(--error);
}

.steam-social-row .steam-social-friend-actions {
  width: 100%;
  justify-content: center;
}

.steam-social-row .steam-friend-btn--add {
  width: 100%;
  justify-content: center;
  background: var(--brand);
  border-color: transparent;
  color: var(--text-on-brand);
  font-weight: 600;
}

.steam-social-row .steam-friend-btn--add:hover {
  background: var(--brand-hover);
  border-color: transparent;
  transform: translateY(-1px);
}

.steam-social-row .steam-friend-btn--sent {
  width: 100%;
  justify-content: center;
  background: var(--surface-1);
}

.steam-social-empty {
  padding: 24px 16px;
  text-align: center;
  color: var(--text-secondary);
  font-size: 13px;
}

.steam-profile-friend-action {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
}

.steam-reaction-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  flex-wrap: wrap;
}

.steam-reaction-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border: 1px solid var(--glass-border);
  border-radius: 25px;
  background: var(--glass);
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease,
    transform 0.1s ease;
  backdrop-filter: blur(24px);
}

.steam-reaction-btn:hover {
  border-color: var(--brand);
  color: var(--text-primary);
  transform: translateY(-1px);
}

.steam-reaction-btn--active {
  color: var(--brand);
  border-color: var(--brand-dim);
  background: var(--brand-dim);
}

.steam-reaction-count {
  font-size: 11px;
  opacity: 0.85;
}

.steam-community-leaderboard {
  margin-bottom: 18px;
}

.steam-community-list {
  flex: 1;
  min-width: 0;
}

@media (min-width: 900px) {
  .steam-community-body {
    flex-direction: row;
    align-items: flex-start;
  }

  .steam-community-leaderboard {
    width: 320px;
    flex: 0 0 320px;
    margin-bottom: 0;
  }
}

.steam-leaderboard {
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  padding: 14px;
}

.steam-leaderboard-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.steam-leaderboard-title {
  font-size: 14px;
  font-weight: 600;
}

.steam-leaderboard-tabs {
  display: flex;
  gap: 6px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.steam-leaderboard-tab {
  padding: 5px 10px;
  border: 1px solid var(--glass-border);
  border-radius: 25px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  transition:
    color 0.15s ease,
    border-color 0.15s ease,
    background 0.15s ease;
}

.steam-leaderboard-tab:hover {
  color: var(--text-primary);
  border-color: var(--brand);
}

.steam-leaderboard-tab--active {
  color: var(--brand);
  border-color: var(--brand-dim);
  background: var(--brand-dim);
}

.steam-leaderboard-rows {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.steam-leaderboard-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 8px;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.steam-leaderboard-row:hover {
  background: rgba(255, 255, 255, 0.05);
}

.steam-leaderboard-rank {
  width: 20px;
  text-align: center;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
}

.steam-leaderboard-avatar {
  width: 26px;
  height: 26px;
  border-radius: 25px;
  object-fit: cover;
  flex-shrink: 0;
}

.steam-leaderboard-avatar--default {
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--glass);
  color: var(--text-secondary);
  font-size: 12px;
}

.steam-leaderboard-name {
  flex: 1;
  font-size: 13px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.steam-leaderboard-value {
  font-size: 12px;
  color: var(--text-secondary);
  white-space: nowrap;
}

.steam-leaderboard-empty,
.steam-leaderboard-loading {
  padding: 16px;
  text-align: center;
  color: var(--text-secondary);
  font-size: 13px;
}

.steam-friends-window {
  background: var(--bg-base);
  border-top: 1px solid #1a8fc5;
  background-image: linear-gradient(to right, #0e6a83, #223a7c);
  background-size: 100% 1px;
  background-repeat: no-repeat;
  background-position: top;
}

.friends-profile-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 15px;
  background: linear-gradient(180deg, #262b31 0%, #101c24);
  border-bottom: 1px solid var(--glass-border);
}

.friends-profile-img {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  padding: 2px;
  border: 2px solid #2e3539;
  background: linear-gradient(180deg, #2e3539, #1c2023);
}

.friends-profile-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.friends-profile-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.friends-name-line {
  display: flex;
  align-items: center;
  gap: 6px;
}

.friends-name {
  font-size: 16px;
  font-weight: 700;
  color: #66c0f4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.friends-status {
  display: flex;
  align-items: center;
  font-size: 12px;
}

.friends-status-text {
  color: #386885;
}

.friends-status-text--online {
  color: #57cbde;
}

.friends-status-text--offline {
  color: #8f98a0;
}

.friends-status-text--invisible {
  color: #7a7a7a;
}

.steam-friends-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin: 10px 12px 0;
  padding: 8px 10px;
  border: 1px dashed #1b3d54;
  border-radius: 3px;
  background: rgba(14, 26, 36, 0.5);
  color: #2f7ca8;
  font-size: 12px;
}

.steam-friends-banner-gotit {
  flex-shrink: 0;
  padding: 3px 8px;
  border: none;
  border-radius: 2px;
  background: #1b6885;
  color: #ffffff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.steam-friends-banner-gotit:hover {
  background: #237fa3;
}

.steam-friends-head {
  padding: 4px 12px 0;
  background-color: #434953;
}

.steam-friends-head-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.steam-friends-title {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.5px;
  color: #8f98a0;
}

.steam-friends-actions {
  display: flex;
  align-items: center;
  gap: 2px;
}

.steam-friends-icon-btn,
.steam-friends-add-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 26px;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: #8f98a0;
  font-size: 14px;
  cursor: pointer;
  transition:
    color 0.15s ease,
    background 0.15s ease;
}

.steam-friends-icon-btn:hover,
.steam-friends-add-btn:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.06);
}

.steam-friends-icon-btn--active {
  color: #66c0f4;
}

.steam-friends-add-btn {
  width: 30px;
}

.steam-friends-search {
  display: none;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  padding: 5px 10px;
  border: 1px solid var(--glass-border);
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.25);
  color: #8f98a0;
  font-size: 12px;
}

.steam-friends-search--open {
  display: flex;
}

.steam-friends-search input {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  color: var(--text-primary);
  font-size: 13px;
}

.steam-friends-search input::placeholder {
  color: #5f6e78;
}

.friends-live-panel {
  flex: 1;
  overflow-y: auto;
  padding: 8px 12px 14px;
  margin-top: 8px;
  scrollbar-width: thin;
  scrollbar-color: #3d4450 #1f232b;
}

.friends-requests-inline {
  margin: 0 12px;
  border: 1px solid #1f2933;
  border-radius: 8px;
  background: rgba(18, 25, 32, 0.9);
  overflow: hidden;
}

.friends-requests-inline[hidden] {
  display: none;
}

.friends-requests-inline .steam-social-list {
  max-height: 240px;
  overflow-y: auto;
  padding: 6px;
}

.friends-requests-inline .steam-social-empty,
.friends-requests-inline .steam-social-loading {
  padding: 14px;
  font-size: 12px;
  text-align: center;
}

.friends-live-panel::-webkit-scrollbar {
  width: 8px;
}

.friends-live-panel::-webkit-scrollbar-track {
  background: #1f232b;
}

.friends-live-panel::-webkit-scrollbar-thumb {
  background: #3d4450;
  border-radius: 4px;
}

.steam-friend-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.steam-friend-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.steam-friend-group-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 2px 6px;
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  width: 100%;
  text-align: left;
  border-radius: 3px;
}

.steam-friend-group-head:hover {
  background: rgba(255, 255, 255, 0.04);
}

.steam-friend-group-chevron {
  width: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #8f98a0;
  font-size: 11px;
  transition: transform 0.15s ease;
}

.steam-friend-group--open .steam-friend-group-chevron {
  transform: rotate(90deg);
}

.steam-friend-group-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.steam-friend-group:not(.steam-friend-group--open) .steam-friend-group-body {
  display: none;
}

.steam-friend-group-title {
  flex: 1;
  font-size: 13px;
  font-weight: 700;
  color: #66c0f4;
}

.steam-friend-group-count {
  font-size: 11px;
  color: #616a73;
}

.steam-friend-group--online .steam-friend-group-title {
  color: #65a2c4;
}

.steam-friend-group--online .steam-friend-group-title,
.steam-friend-group--offline .steam-friend-group-title {
  color: #8f98a0;
}

.steam-friend-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 46px;
  padding: 5px 8px;
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.12s ease;
}

.steam-friend-row:hover {
  background: rgba(255, 255, 255, 0.05);
}

.steam-friend-avatar-frame {
  position: relative;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  padding: 2px;
  border: 2px solid var(--glass-border);
  background: var(--glass);
}

.steam-friend-row--ingame .steam-friend-avatar-frame {
  border-color: #90ba3c;
}

.steam-friend-row--online .steam-friend-avatar-frame {
  border-color: #4ea8c8;
}

.steam-friend-avatar {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.steam-friend-avatar--default {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-size: 14px;
}

.steam-friend-game-badge {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 3px;
  overflow: hidden;
  background: var(--glass);
}

.steam-friend-game-badge img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.steam-friend-game-badge i {
  font-size: 11px;
  color: var(--text-secondary);
}

.steam-friend-game-badge--empty {
  background: transparent;
}

.steam-friend-info {
  flex: 1;
  min-width: 0;
}

.steam-friend-name-line {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.steam-friend-game-title,
.steam-friend-presence {
  font-size: 12px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.steam-friend-row--ingame .steam-friend-game-title {
  color: #90ba3c;
}

.steam-friend-row--online .steam-friend-presence {
  color: #65c0c4;
}

.steam-friend-row--offline .steam-friend-presence {
  color: #616a73;
}

.steam-friend-game-status {
  font-size: 11px;
  color: #5c7e10;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.steam-friends-favorites {
  padding: 8px;
  border-bottom: 1px solid var(--glass-border);
}

.steam-friends-favorites-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, 40px);
  gap: 6px;
  padding: 8px 0 2px;
}

.steam-favorites-dragover {
  outline: 2px dashed var(--brand);
}

.steam-friends-favorites-empty {
  grid-column: 1 / -1;
  padding: 8px 12px;
  border: 1px dashed var(--glass-border);
  border-radius: 6px;
  font-size: 11px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 6px;
  justify-content: center;
  background: var(--glass);
  pointer-events: none;
}

.steam-fav-box {
  position: relative;
  width: 40px;
  height: 40px;
  padding: 2px;
  border: 2px solid var(--glass-border);
  border-radius: 6px;
  background: var(--glass);
  cursor: pointer;
  overflow: hidden;
}

.steam-fav-box--ingame {
  border-color: #90ba3c;
}

.steam-fav-box--online {
  border-color: #4ea8c8;
}

.steam-fav-box--offline {
  border-color: var(--glass-border);
}

.steam-fav-box img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.steam-fav-remove {
  position: absolute;
  top: 0;
  right: 0;
  width: 16px;
  height: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: var(--glass);
