}

.steam-feed-time {
  font-size: 12px;
  color: var(--text-secondary);
}

.dm-window {
  display: flex;
  flex-direction: column;
  height: 100%;
  color: var(--text-primary);
  overflow: hidden;
}

.dm-header {
  padding: 12px 14px;
