}

.dm-header-status {
  font-size: 12px;
  color: var(--text-secondary);
}

.dm-messages {
  flex: 1;
  overflow-y: auto;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.dm-empty {
  color: var(--text-secondary);
