html.steamdeck-mode,
#steamdeck-root,
#steamdeck-qta {
  --brand: #66c0f4;
  --brand-strong: #6ff154;
  --text-primary: #dcdedf;
  --text-secondary: #8f98a0;
  --bg-primary: #171a21;
  --bg-secondary: #202126;
  --deck-page-bg: #0b1117;
  --glass: rgba(23, 29, 37, 0.72);
  --glass-border: rgba(255, 255, 255, 0.08);
  --error: #ff5c5c;
}

#steamdeck-root {
  position: fixed;
  inset: 0;
  z-index: 998;
  display: flex;
  flex-direction: column;
  color: var(--text-primary);
  font-size: 14px;
  user-select: none;
  overflow: hidden;
  background:
    radial-gradient(
      120% 90% at 50% 0%,
      rgba(42, 71, 94, 0.55) 0%,
      transparent 55%
    ),
    linear-gradient(180deg, #151921 0%, #16243a 100%);
}

.deck-shell {
  display: flex;
