.deck-topbar-search:hover {
  background: var(--brand);
  color: #fff;
}

.deck-topbar-quick {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: none;
  background: transparent;
  color: var(--text-primary);
  font-size: 14px;
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.deck-topbar-quick:hover {
  background: var(--brand);
  color: #fff;
}

.deck-topbar-power {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: none;
