  flex: 1;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) rgba(255, 255, 255, 0.05);
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding-right: 4px;
}

.deck-main::-webkit-scrollbar {
  width: 8px;
}

.deck-main::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.05);
  border-radius: 4px;
}

.deck-main::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 4px;
}

.deck-main::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.3);
}

.deck-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.deck-recent-games {
  position: relative;
}

.deck-recent-bg {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 420px;
  z-index: 0;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s ease;
}

.deck-recent-bg-visible {
  opacity: 0.55;
}

.deck-recent-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(6, 10, 13, 0.55),
    rgba(6, 10, 13, 0.88)
  );
}

.deck-bg-layer {
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  transition:
    opacity 0.6s ease,
    transform 0.7s ease;
  transform: scale(1.12);
}

.deck-bg-layer-active {
  opacity: 1;
  transform: scale(1);
}

.deck-bg-layer img,
.deck-bg-layer i {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: blur(10px) saturate(1.1);
  animation: deckBgFloat 14s ease-in-out infinite;
}

.deck-bg-layer i {
  display: block;
  font-size: 260px;
  line-height: 1;
  text-align: center;
  color: var(--brand);
  opacity: 0.7;
  padding-top: 8%;
}

@keyframes deckBgFloat {
  0%,
  100% {
    transform: scale(1.02) translate(0, 0);
  }
  25% {
    transform: scale(1.08) translate(1.5%, -1.5%);
  }
  50% {
    transform: scale(1.04) translate(-1.5%, 1.5%);
  }
  75% {
    transform: scale(1.09) translate(1%, 1%);
  }
}

.deck-section-title {
