.deck-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--text-primary);
  font-family: inherit;
  cursor: pointer;
  text-align: left;
  outline: none;
  isolation: isolate;
}

.deck-tile-art {
  position: relative;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  aspect-ratio: 3 / 4;
  overflow: hidden;
  transition: transform 0.22s ease-out;
}

.deck-tile::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0%;
  width: 130%;
  height: 130%;
  background-image: var(--tile-art, none);
  background-size: cover;
  background-position: center;
  filter: blur(28px) saturate(1.2);
  opacity: 0;
  pointer-events: none;
  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
  z-index: -1;
}

.deck-tile:hover::before,
.deck-tile.deck-focused::before {
  opacity: 0.7;
  transform: translateX(-50%) translateY(0) scale(1);
}

.deck-tile:hover .deck-tile-art {
  transform: scale(1.03);
}

.deck-tile-art::after {
  content: "";
  position: absolute;
  inset: 0;
  border: 2px solid transparent;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.22s ease-out;
}

.deck-tile.deck-focused .deck-tile-art::after {
  opacity: 1;
  animation:
    deckFocusBorderIn 0.1s ease-out,
    deckFocusBreathe 2.6s ease-in-out infinite;
}

@keyframes deckFocusBorderIn {
  0% {
    border-width: 2px;
  }
  100% {
    border-width: 2px;
  }
}

@keyframes deckFocusBreathe {
  0%,
  100% {
    border-color: rgba(117, 123, 125, 0.3);
  }
  50% {
    border-color: rgba(117, 123, 125, 1);
  }
}

.deck-tile-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  user-drag: none;
  -webkit-user-drag: none;
  user-select: none;
  -webkit-user-select: none;
  cursor: pointer;
}

.deck-tile-icon {
