#steamdeck-qta {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  display: none;
  z-index: 99990;
  font-size: 13px;
}

#steamdeck-qta.open {
  display: block;
}

#steamdeck-qta.closing {
  display: block;
  pointer-events: none;
}

#steamdeck-qta.open .deck-qta-shell {
  animation: deck-qta-slide-in 0.3s cubic-bezier(0.22, 1, 0.36, 1) both;
}

#steamdeck-qta.closing .deck-qta-shell {
  animation: deck-qta-slide-out 0.2s cubic-bezier(0.55, 0, 1, 0.45) both;
}

body:has(#steamdeck-qta.open) #context-menu {
  z-index: 100000;
}

@keyframes deck-qta-slide-in {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes deck-qta-slide-out {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(100%);
    opacity: 0;
  }
}

.deck-qta-shell {
  display: flex;
  height: 100%;
  width: 400px;
  max-width: 86vw;
  background: #12161a;
  border-left: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.6);
}

.deck-qta-rail {
  display: flex;
  flex-direction: column;
