  --particle-star-a: #f4f1ff;
  --particle-star-b: #cabdf7;
  --particle-rain: #b9c8e8;
  --particle-bubble: #a8c6eb;
  --particle-firefly-a: #d9ff6a;
  --particle-firefly-b: #ffe98a;
  --particle-ember-a: #ff7a2a;
