  left: 100%;
  top: 0;
  background: var(--menu-bg);
  border: 1px solid var(--glass-border);
  box-shadow: 0 8px 32px var(--shadow-color);
  min-width: 180px;
  padding: 4px 0;
  border-radius: var(--r);
  backdrop-filter: blur(32px);
}

.dropdown-submenu:hover .submenu {
  display: block;
}

.notepad-content {
