}

.notepad-dialog input[type="text"],
.notepad-dialog input[type="number"] {
  flex: 1;
  padding: 8px 12px;
  border: 1px solid var(--glass-border);
  border-radius: var(--r-sm);
  background: var(--surface-1);
  color: var(--text-primary);
