  border: 1px solid var(--glass-border);
  border-radius: var(--r-sm);
  background: var(--surface-1);
  color: var(--text-primary);
  outline: none;
  cursor: pointer;
  font-size: 13px;
  transition: border-color 0.15s;
}

.notepad-dialog select:focus {
  border-color: var(--brand);
}

.notepad-dialog select option {
  background: var(--surface-2);
  color: var(--text-primary);
}

.notepad-dialog-buttons {
  margin-top: 20px;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.notepad-dialog button {
  padding: 8px 20px;
  cursor: pointer;
  border: 1px solid var(--glass-border);
  border-radius: var(--r-sm);
  background: var(--glass);
  font-size: 13px;
  transition:
    background 0.15s,
    border-color 0.15s;
}

.notepad-dialog button:hover {
  background: var(--glass-hover);
  border-color: var(--glass-border);
}

.notepad-dialog button.primary {
  background: var(--brand-dim);
  color: var(--text-primary);
  border-color: var(--brand);
}

.notepad-dialog button.primary:hover {
  background: var(--brand);
  border-color: var(--brand-hover);
}

.notepad-dialog-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 13px;
}

.notepad-dialog-checkbox input[type="checkbox"] {
  width: 16px;
  height: 16px;
  accent-color: var(--brand);
  cursor: pointer;
}

.font-preview {
