  justify-content: center;
  overflow: hidden;
  flex-shrink: 0;
}
.start-picker-preview-box img {
  width: 32px;
  height: 32px;
  object-fit: contain;
}
.start-picker-tabs {
  display: flex;
  gap: 6px;
  padding: 10px 12px 0 12px;
  border-bottom: 1px solid var(--glass-border);
  background: var(--surface-1);
