  font-weight: 500;
  cursor: pointer;
  transition:
    background 0.15s,
    color 0.15s;
}
.start-picker-tab:hover {
  background: var(--glass);
  color: var(--text-primary);
}
.start-picker-tab.active {
  background: var(--surface-2);
  border-color: var(--glass-border);
  color: var(--brand);
}
.start-picker-content {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: var(--surface-1);
}
.start-picker-panel {
  display: none;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  padding: 12px;
  gap: 10px;
}
.start-picker-panel.active {
  display: flex;
}
.start-picker-search-wrap {
  flex-shrink: 0;
}
.start-picker-search {
  width: 100%;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  background: var(--surface-2);
  color: var(--text-primary);
  font-size: 13px;
  outline: none;
  transition: border-color 0.15s;
  box-sizing: border-box;
}
.start-picker-search::placeholder {
  color: var(--text-muted);
}
.start-picker-search:focus {
  border-color: var(--brand);
  box-shadow: 0 0 0 2px var(--brand-dim);
}
.start-picker-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(56px, 1fr));
  gap: 8px;
  overflow-y: auto;
  flex: 1;
  min-height: 160px;
  max-height: 42vh;
  padding: 4px;
  align-content: start;
}
.start-picker-grid::-webkit-scrollbar {
  width: 8px;
}
.start-picker-grid::-webkit-scrollbar-thumb {
  background: var(--glass-hover);
  border-radius: 6px;
}
.start-picker-icon {
  width: 56px;
  height: 56px;
  border-radius: 10px;
  background: var(--surface-2);
  border: 1px solid var(--glass-border);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition:
    background 0.15s,
    border-color 0.15s,
    transform 0.1s;
  overflow: hidden;
}
.start-picker-icon:hover {
  background: var(--glass-hover);
  border-color: var(--brand);
  transform: translateY(-1px);
}
.start-picker-icon.selected {
  border-color: var(--brand);
  background: var(--brand-dim);
  box-shadow: 0 0 0 2px var(--brand-dim);
}
.start-picker-icon img {
  width: 36px;
  height: 36px;
  object-fit: contain;
}
.start-picker-empty {
  grid-column: 1 / -1;
  text-align: center;
  padding: 24px;
  color: var(--text-muted);
  font-size: 13px;
}
.start-picker-upload-zone {
  border: 1.5px dashed var(--glass-border);
  border-radius: 12px;
  background: var(--surface-2);
  padding: 28px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  transition:
    border-color 0.15s,
    background 0.15s;
  color: var(--text-secondary);
  text-align: center;
}
.start-picker-upload-zone:hover,
.start-picker-upload-zone.dragover {
  border-color: var(--brand);
  background: var(--brand-dim);
  color: var(--text-primary);
}
.start-picker-upload-zone i {
  font-size: 28px;
  color: var(--brand);
}
.start-picker-upload-hint {
  font-size: 11px;
  color: var(--text-muted);
}
.start-picker-upload-preview {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border-radius: 10px;
  background: var(--surface-2);
  border: 1px solid var(--glass-border);
}
.start-picker-upload-preview img {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  object-fit: contain;
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
}
.start-picker-upload-name {
  font-size: 12px;
  color: var(--text-secondary);
  word-break: break-all;
}
.start-picker-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid var(--glass-border);
  background: var(--surface-2);
  flex-shrink: 0;
}
.start-picker-btn {
  padding: 8px 16px;
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition:
    background 0.15s,
    border-color 0.15s,
    color 0.15s;
