html.win11-mode #yukiOS-settings .win11-settings {
  --txt_clr-rgb: 255 255 255;
  --clrPrm: var(--win11-accent);
  --alt-txt: #000000;
  --sat-txt: #999999;
  --dark-txt: #ffffff;
  --base_bg-rgb: 32 32 32;
  --bg: var(--win11-mica-base);
  --fakeMica: var(--win11-mica-base)
    radial-gradient(var(--win11-mica-tint) 25%, var(--win11-mica-base) 100%)
    no-repeat fixed;
  --tile-bg: var(--win11-tile-dark);
  --tile-bg-hover: var(--win11-tile-dark-hover);
  --tile-border: var(--win11-tile-border);
  --tile-shadow: none;
  --search-bg: var(--win11-search-dark);
  --search-bg-hover: var(--win11-search-dark-hover);
  --select-bg: var(--win11-select-dark);
}

html.win11-mode[data-theme-mode="light"] #yukiOS-settings .win11-settings {
  --txt_clr-rgb: 0 0 0;
  --clrPrm: var(--win11-accent-light);
  --alt-txt: #ffffff;
  --sat-txt: #777777;
  --dark-txt: #000000;
  --base_bg-rgb: 243 243 243;
  --bg: var(--win11-mica-light-base);
  --fakeMica: var(--win11-mica-light-base)
    radial-gradient(
      var(--win11-mica-light-tint) 75%,
      var(--win11-mica-light-base) 100%
    )
    no-repeat fixed;
  --tile-bg: var(--win11-tile-light);
  --tile-bg-hover: var(--win11-tile-light-hover);
  --tile-border: var(--win11-tile-border);
  --tile-shadow: none;
  --search-bg: var(--win11-search-light);
  --search-bg-hover: var(--win11-search-light-hover);
  --select-bg: var(--win11-select-light);
}

html.transparent-ui.tp-window-body.win11-mode #yukiOS-settings .win11-settings {
  --fakeMica: color-mix(in srgb, var(--win11-mica-base) 82%, transparent)
    radial-gradient(
      color-mix(in srgb, var(--win11-mica-tint) 88%, transparent) 25%,
      color-mix(in srgb, var(--win11-mica-base) 82%, transparent) 100%
    )
    no-repeat fixed;
  backdrop-filter: blur(var(--tp-blur-window, 40px)) saturate(1.4);
  -webkit-backdrop-filter: blur(var(--tp-blur-window, 40px)) saturate(1.4);
