html.win11-mode #yukiOS-settings .win11-settings .restWindow {
  font-size: 14px;
  height: 100%;

  container-type: inline-size;
  container-name: appWrapper;

  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  nav {
    position: absolute;
    left: 0;
    width: 300px;
    height: 100%;
    display: flex;
    flex-direction: column;

    .nav_top {
      .account {
        border-radius: 4px;
        display: flex;
        align-items: center;
        gap: 16px;
        padding: 8px;
        margin: 8px;

        &:hover {
          background: rgb(var(--txt_clr-rgb) / 3.33%);
        }

        div p {
          &:first-child {
            font-weight: 500;
          }
          &:last-child {
            font-size: smaller;
          }
        }
      }

      .search {
        background: var(--search-bg);
        height: 32px;
        width: calc(300px - 32px);
        border: 0;
        border-bottom: 1px solid var(--clrPrm);
        border-radius: 4px;
        padding: 8px;
        margin: 8px 16px 20px;
        color: var(--dark-txt);

        &:hover {
          background: var(--search-bg-hover);
        }
        &:focus {
          border-bottom: 2px solid var(--clrPrm);
        }
        &:focus-visible {
          outline: none;
        }

        &::placeholder {
          color: rgb(var(--txt_clr-rgb) / 66%);
        }
      }
    }

    .nav_bottom {
      display: flex;
      flex-direction: column;
      overflow: overlay;
      position: relative;

      .navLink {
        position: relative;
        overflow: hidden;
        height: 36px;
        padding-left: 7px;
        margin: 2px 16px;
        border-radius: 4px;
        display: flex;
        align-items: center;
        flex-shrink: 0;
        cursor: pointer;

        &:hover,
        &.selected {
          background: rgb(var(--txt_clr-rgb) / 5%);
        }

        img {
          margin: 0 10.5px 0 7px;
        }
      }

      .marker {
        position: absolute;
        background: var(--clrPrm);
        height: 16px;
        width: 3px;
        border-radius: 3px;
        top: 0;
        left: 16px;
        transform: translateY(12px);
        transition: transform 250ms cubic-bezier(1, 0, 0, 1);
      }

      .navLink:nth-child(1).selected ~ .marker {
        transform: translateY((40 * (1 - 1) + 12) + px);
      }
      .navLink:nth-child(2).selected ~ .marker {
        transform: translateY((40 * (2 - 1) + 12) + px);
      }
      .navLink:nth-child(3).selected ~ .marker {
        transform: translateY((40 * (3 - 1) + 12) + px);
      }
      .navLink:nth-child(4).selected ~ .marker {
        transform: translateY((40 * (4 - 1) + 12) + px);
      }
      .navLink:nth-child(5).selected ~ .marker {
        transform: translateY((40 * (5 - 1) + 12) + px);
      }
      .navLink:nth-child(6).selected ~ .marker {
        transform: translateY((40 * (6 - 1) + 12) + px);
      }
      .navLink:nth-child(7).selected ~ .marker {
        transform: translateY((40 * (7 - 1) + 12) + px);
      }
      .navLink:nth-child(8).selected ~ .marker {
        transform: translateY((40 * (8 - 1) + 12) + px);
      }
      .navLink:nth-child(9).selected ~ .marker {
        transform: translateY((40 * (9 - 1) + 12) + px);
      }
      .navLink:nth-child(10).selected ~ .marker {
        transform: translateY((40 * (10 - 1) + 12) + px);
      }
      .navLink:nth-child(11).selected ~ .marker {
        transform: translateY((40 * (11 - 1) + 12) + px);
      }
      .navLink:nth-child(12).selected ~ .marker {
        transform: translateY((40 * (12 - 1) + 12) + px);
      }
    }
  }

  main {
    margin-left: 300px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    height: 100%;
    flex: 1 1 auto;
    min-height: 0;

    .sysTop {
      width: min(100%, 1000px);
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      padding: 8px 0 14px;
      gap: 8px;

      .left {
        display: flex;
        align-items: center;

        .device_img {
          height: 70px;
          border: 4px solid black;
          border-radius: 4px;
        }
        .column_device {
          margin-left: 16px;

          .device_name {
            font-size: 18px;
            font-weight: 500;
          }
          .device_model {
            color: rgb(var(--txt_clr-rgb) / 90%);
          }
          .device_rename {
            color: var(--clrPrm);
          }
        }
      }

      .right {
        display: flex;

        .column {
          display: flex;
          align-items: center;
          border-radius: 4px;
          padding: 8px;
          &:hover {
            background: rgb(var(--txt_clr-rgb) / 5%);
          }

          p {
            font-weight: 500;
            padding: 0 12px;

            .column_lower {
              color: rgb(var(--txt_clr-rgb) / 60%);
              font-size: 13px;
              font-weight: 400;
            }
          }
        }
      }
    }

    .netTop {
      width: min(100%, 1000px);
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 12px;
      gap: 1rem;

      div:first-child {
        display: flex;
        align-items: center;
        gap: 10px;
      }

      .box {
        display: flex;
        padding: 8px;
        gap: 10px;
        align-items: center;
        border-radius: 4px;

        .settingsIcon {
          margin: 0;
        }

        &:hover {
          background: rgb(var(--txt_clr-rgb) / 5%);
        }

        h3 {
          font-weight: 500;
          font-size: 14px;
        }
        p {
          font-size: 12px;
          color: rgb(var(--txt_clr-rgb) / 67%);
        }
      }
    }

    .personaliseTop {
      display: flex;
      flex-wrap: wrap;
      margin-bottom: 20px;
      gap: 12px;

      .mainImg {
        height: 200px;
        border: 8px solid black;
        border-radius: 1rem;
        margin-right: 32px;
      }

      div {
        h3 {
          font-size: 14px;
          font-weight: 500;
          padding-bottom: 8px;
        }
        .bgBox {
          display: grid;
          grid-template-columns: repeat(3, 1fr);
          grid-template-rows: repeat(2, 1fr);
          gap: 8px;

          img {
            width: 120px;
            border-radius: 4px;
          }

          .selected {
            box-shadow:
              0 0 0 2px var(--bg),
              0 0 0 4px var(--clrPrm);
            border-radius: 2px;
          }
        }
      }
    }

    .accountsTop {
      display: flex;
      gap: 16px;
      align-items: center;
      margin: 1rem 0;

      div p {
        &:first-child {
          font-size: 16px;
        }
        &:nth-child(2),
        &:last-child {
          color: rgb(var(--txt_clr-rgb) / 67%);
        }
      }
    }

    .langSwitcherTile {
      &::after {
        display: none;
      }

      select {
        background: var(--surface-1);
        border: 1px solid var(--glass-border);
        border-bottom: 1px solid var(--glass-border);
        color: rgb(var(--txt_clr-rgb));
        height: 32px;
        padding-left: 8px;
        border-radius: 6px;
      }
    }

    .updateTop {
      display: flex;
      width: min(100%, 1000px);
      align-items: center;
      gap: 1rem;

      .btn {
        background: var(--clrPrm);
        color: var(--alt-txt);
        padding: 6px 12px;
        border-radius: 4px;
        border: 0;
        cursor: pointer;
      }

      .left {
        display: flex;
        align-items: center;
        gap: 1rem;

        div {
          h2 {
            font-size: 18px;
            font-weight: 600;
          }
          p {
            font-size: 14px;
            color: rgb(var(--txt_clr-rgb) / 67%);
          }
        }
      }
      .right {
        flex-shrink: 0;
        margin-left: auto;
      }
    }

    .timeTop {
      h1 {
        padding: 0;
        font-size: 40px;
        font-weight: 600;
      }
    }

    h1 {
      padding: 14px 24px;
      font-weight: 500;
      font-size: 28px;
      flex-shrink: 0;
    }

    .tilesCont {
      padding: 0 24px 44px;
      overflow-y: overlay;
      display: flex;
      flex-direction: column;
      gap: 4px;
      animation: slideUp 0.2s;
      flex-grow: 1;

      .settingsIcon {
        font-size: 20px;
        margin: 0 21px 0 17.5px;
        font-family: SettingsIcons;
      }

      .tile {
        width: min(100%, 1000px);
        min-height: 67px;
        display: flex;
        align-items: center;
        background: var(--tile-bg);
        border-radius: 4px;
        padding: 7px 42px 7px 0;
        border: 1px solid var(--tile-border);
        box-shadow: var(--tile-shadow);
        position: relative;

        &:hover {
          background: var(--tile-bg-hover);
        }
        &::after {
          content: ">";
          transform: scaleY(2);
          position: absolute;
          right: 16px;
        }

        .tile_content {
          flex-grow: 1;
        }
        .tile_desc {
          color: rgb(var(--txt_clr-rgb) / 66%);
          font-size: 12.33px;
        }

        &.square {
          width: 220px;
          height: 220px;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          flex-shrink: 0;
          padding: 0;
          font-weight: 500;

          .settingsIcon {
            font-size: 48px;
          }
        }

        &.thin-blue {
          min-height: unset;
          height: unset;
          color: var(--clrPrm);
          justify-content: center;
          margin: 4px 0;
        }

        &.thin-blue::after,
        &.square::after {
          display: none;
        }

        &.clickable {
          cursor: pointer;
        }
      }

      .subHeading {
        font-weight: 500;
        height: 45px;
        display: flex;
        align-items: center;
        flex-shrink: 0;
      }

      .spacer {
        padding: 8px;
      }
    }
  }

  .navMenuBtn {
    display: none;
  }

  @container appWrapper (max-width: 800px) {
    .navMenuBtn {
      display: flex;
      position: absolute;
      top: 8px;
      right: 8px;
      padding: 12px;
      border-radius: 6px;
      cursor: pointer;

      &:hover {
        background: rgb(var(--txt_clr-rgb) / 5%);
      }

      svg {
        transition: all 0.1s;
      }
      &:active svg {
        transform: scaleX(0.67);
      }
    }

    main {
      margin-left: 0;
    }
    nav {
      background: var(--bg);
      z-index: 999;
      transform: translateX(-100%);
      transition: all 0.2s cubic-bezier(0, 0, 0, 1);

      &.open {
        transform: translateX(0);
      }
    }
  }
}

html.win11-mode[data-theme-mode="light"]
  #yukiOS-settings
  .win11-settings
  .restWindow {
