html.win11-mode #yukiOS-settings .win11-settings .restWindow {
  .win11-subpage-head {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 24px 0;
    flex-shrink: 0;
  }

  .win11-back {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: transparent;
    border: 0;
    color: var(--dark-txt);
    font-size: 14px;
    padding: 6px 10px;
    border-radius: 4px;
    cursor: pointer;

    &:hover {
      background: rgb(var(--txt_clr-rgb) / 5%);
    }
  }

  .win11-control {
    width: min(100%, 1000px);
    display: flex;
    align-items: center;
    gap: 16px;
    background: var(--tile-bg);
    border-radius: 4px;
    padding: 12px 16px;
    border: 1px solid var(--tile-border);
    box-shadow: var(--tile-shadow);

    &--stacked {
      flex-direction: column;
      align-items: stretch;
      gap: 10px;
    }
  }

  .win11-control__text {
    flex-grow: 1;
    min-width: 0;
  }

  .win11-control__title {
    font-size: 14px;
    font-weight: 400;
  }

  .win11-control__desc {
    color: rgb(var(--txt_clr-rgb) / 66%);
    font-size: 12.33px;
    margin-top: 2px;
  }

  .win11-switch {
    appearance: none;
    -webkit-appearance: none;
    width: 40px;
    height: 20px;
    border-radius: 10px;
    border: 1px solid var(--txt-clr-rgb, var(--glass-border));
    border: 1px solid rgb(var(--txt_clr-rgb) / 40%);
    background: transparent;
    position: relative;
    cursor: pointer;
    flex-shrink: 0;
    transition:
      background 0.15s ease,
      border-color 0.15s ease;
    padding: 0;

    .win11-switch__thumb {
      position: absolute;
      top: 50%;
      left: 4px;
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: var(--dark-txt);
      transform: translateY(-50%);
      transition:
        left 0.15s ease,
        background 0.15s ease;
    }

    &.is-on {
      background: var(--clrPrm);
      border-color: var(--clrPrm);

      .win11-switch__thumb {
        left: 22px;
        background: var(--alt-txt);
      }
    }

    &:focus-visible {
      outline: 2px solid var(--clrPrm);
      outline-offset: 2px;
    }
  }

  .win11-range {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 240px;
    flex-shrink: 0;
  }

  .win11-range-value {
    min-width: 48px;
    text-align: right;
    font-size: 13px;
    color: rgb(var(--txt_clr-rgb) / 80%);
  }

  .win11-segment {
    display: inline-flex;
    border: 1px solid var(--glass-border);
    border-radius: 4px;
    overflow: hidden;
    flex-shrink: 0;

    .win11-segment__btn {
      background: transparent;
      border: 0;
      border-right: 1px solid var(--glass-border);
      color: var(--dark-txt);
      font-size: 13px;
      padding: 7px 14px;
      cursor: pointer;

      &:last-child {
        border-right: 0;
      }

      &.active {
        background: var(--clrPrm);
        color: var(--alt-txt);
      }
    }
  }

  .win11-input {
    background: var(--tile-bg);
    border: 1px solid var(--tile-border);
    border-bottom-color: var(--clrPrm);
    border-radius: 4px;
    color: var(--dark-txt);
    font-size: 13px;
    padding: 8px 10px;
    min-width: 240px;

    &:focus {
      outline: none;
      border-bottom-width: 2px;
    }
  }

  .win11-action {
    background: var(--tile-bg);
    border: 1px solid var(--tile-border);
    border-radius: 4px;
    color: var(--dark-txt);
    font-size: 13px;
    padding: 8px 14px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;

    &:hover {
      background: var(--tile-bg-hover);
    }

    &.primary {
      background: var(--clrPrm);
      color: var(--alt-txt);
      border-color: var(--clrPrm);
    }

    &.danger {
      background: var(--error);
      color: var(--text-on-brand);
      border-color: var(--error);
    }
  }

  .win11-hero-row {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 12px 0;
  }

  .win11-note {
    color: rgb(var(--txt_clr-rgb) / 66%);
    font-size: 12.33px;
    padding: 6px 2px;
  }

  .win11-empty {
    color: rgb(var(--txt_clr-rgb) / 66%);
    font-size: 13px;
    padding: 12px 2px;
  }

  .win11-theme-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
    gap: 8px;
    width: 100%;
  }

  .win11-theme-swatch {
    appearance: none;
    -webkit-appearance: none;
    border: 1px solid var(--tile-border);
    border-radius: 4px;
    color: #ffffff;
    cursor: pointer;
    font-size: 12px;
    font-weight: 500;
    height: 56px;
    padding: 6px;
    text-align: center;
    transition: outline-color 0.15s ease;

    &:hover {
      outline: 2px solid var(--clrPrm);
      outline-offset: -1px;
    }

    &.active {
      outline: 2px solid var(--clrPrm);
      outline-offset: 1px;
    }
  }

  .win11-theme-item {
    display: flex;
    flex-direction: column;
    gap: 6px;
    width: 100%;
  }

  .win11-theme-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    width: 100%;
  }

  .win11-info {
    width: min(100%, 1000px);
    border: 1px solid var(--tile-border);
    border-radius: 4px;
    background: rgb(var(--txt_clr-rgb) / 2%);
    overflow: hidden;
  }

  .win11-info-row {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 8px 16px;
    font-size: 13px;
    line-height: 1.35;
    color: inherit;
    text-decoration: none;

