  }

  a.win11-info-row {
    cursor: pointer;
    transition: background 0.12s ease;

    &:hover {
      background: rgb(var(--txt_clr-rgb) / 6%);
      text-decoration: none;
    }

    &:focus-visible {
      outline: 2px solid var(--clrPrm);
      outline-offset: -2px;
    }
  }

  .win11-info-label {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 190px;
    flex-shrink: 0;
    color: rgb(var(--txt_clr-rgb) / 66%);
  }

  .win11-info-value {
    flex: 1;
    min-width: 0;
    line-height: 1.35;
