    background: rgb(var(--txt_clr-rgb) / 4%);
    color: inherit;
    text-align: center;
    text-decoration: none;
    transition:
      background 0.12s ease,
      border-color 0.12s ease;

    &:hover {
      background: rgb(var(--txt_clr-rgb) / 7%);
      border-color: rgb(var(--txt_clr-rgb) / 22%);
    }

    &:focus-visible {
      outline: 2px solid var(--clrPrm);
      outline-offset: 2px;
    }
  }

  .win11-service-icon {
    width: 40px;
    height: 40px;
    flex-shrink: 0;
    border-radius: 4px;
    object-fit: contain;
  }

  .win11-service-icon-fallback {
    font-size: 32px;
    line-height: 40px;
    flex-shrink: 0;
    color: rgb(var(--txt_clr-rgb) / 44%);
  }

  .win11-service-name {
    font-size: 13px;
    font-weight: 600;
    line-height: 1.3;
    overflow-wrap: anywhere;
  }

  .win11-service-detail {
    font-size: 12px;
    line-height: 1.3;
    color: rgb(var(--txt_clr-rgb) / 66%);
  }

  .win11-service-credit {
    max-width: 100%;
    margin-top: auto;
    overflow: hidden;
    font-size: 11.5px;
    line-height: 1.3;
    color: rgb(var(--txt_clr-rgb) / 46%);
    text-overflow: ellipsis;
    white-space: nowrap;
