  .win11-logo {
    width: 48px;
    height: 48px;
    flex-shrink: 0;
    border-radius: 4px;
    object-fit: contain;
  }

  .win11-chip-row {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    width: 100%;
  }

  .select-menu {
    min-width: 200px;
    flex-shrink: 0;

    .select-menu__trigger {
      background: var(--select-bg);
      border: 1px solid var(--tile-border);
      border-radius: 4px;
      color: var(--dark-txt);
      padding: 7px 10px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
    }

    .select-menu__dropdown {
      background: var(--tile-bg-hover);
      border: 1px solid var(--tile-border);
      border-radius: 4px;
      box-shadow: 0 8px 24px var(--shadow-color);
    }

    .select-menu__option {
      color: var(--dark-txt);
      font-size: 13px;
      padding: 8px 10px;

      &:hover,
      &.selected {
        background: rgb(var(--txt_clr-rgb) / 8%);
      }
    }
  }

  .range-slider {
    flex: 1;

    .range-slider__track {
      background: rgb(var(--txt_clr-rgb) / 20%);
      height: 4px;
      border-radius: 2px;
    }

    .range-slider__fill {
      background: var(--clrPrm);
    }

    .range-slider__thumb {
      background: var(--clrPrm);
      border: 3px solid var(--bg-primary);
      width: 16px;
      height: 16px;
    }
