.session-overlay.win11-session {
  --win11-lock-fg: rgba(255, 255, 255, 0.94);
  --win11-lock-fg-dim: rgba(255, 255, 255, 0.78);
  --win11-lock-btn-bg: rgba(255, 255, 255, 0.2);
  --win11-lock-btn-bg-active: rgba(255, 255, 255, 0.33);
  --win11-lock-btn-border: rgba(255, 255, 255, 0.33);
  overflow: hidden;
}

.session-overlay.win11-session .session-background {
  -webkit-backdrop-filter: blur(25px) brightness(0.5);
  backdrop-filter: blur(25px) brightness(0.5);
}

.session-overlay.win11-session .session-content > * {
  transition:
    opacity 250ms ease-in-out,
    visibility 0s linear 250ms;
}

.session-overlay.win11-session[data-win11-stage="splash"]
  .session-content
  > *:not(.session-clock-block) {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.session-overlay.win11-session[data-win11-stage="revealed"]
  .session-content
  > *:not(.session-clock-block) {
  opacity: 1;
  visibility: visible;
  transition:
    opacity 250ms ease-in-out,
    visibility 0s linear 0s;
}

.session-overlay.win11-session .session-mode-btn,
.session-overlay.win11-session .user-carousel-tile span,
.session-overlay.win11-session .system-icon {
  color: var(--win11-lock-fg);
}

.session-overlay.win11-session.win11-session-locked
  .session-content
  > *:not(.session-clock-block) {
  display: none;
}

.session-overlay.win11-session .system-actions-row,
.session-overlay.win11-session .session-status-widget,
.session-overlay.win11-session .session-support-btn {
  display: none;
}

.session-overlay.win11-session .session-support-btn,
.session-overlay.win11-session .session-github-btn,
.session-overlay.win11-session .session-discord-btn {
  margin-left: -70px;
}

.session-overlay.win11-session:not(.win11-session-locked)
  .session-features-link {
  display: none;
}

.session-overlay.win11-session .session-clock-block {
  position: absolute;
  top: -200px;
  left: 0;
  width: 100%;
  text-align: center;
  z-index: 2;
  opacity: 1;
  transform: translateY(0);
  transition:
    opacity 200ms ease-in-out,
    transform 200ms ease-in-out;
  pointer-events: none;
}

.session-overlay.win11-session[data-win11-stage="revealed"]
  .session-clock-block {
  opacity: 0;
  transform: translateY(-200px);
}

.session-overlay.win11-session .session-time {
  font-size: 60px;
  font-weight: 600;
  letter-spacing: normal;
  line-height: 1.1;
  color: var(--win11-lock-fg);
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.session-overlay.win11-session .session-date {
  margin-top: 4px;
  margin-bottom: 0;
  font-size: 18px;
  font-weight: 500;
  color: var(--win11-lock-fg-dim);
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.5);
}

.session-overlay.win11-session .user-carousel-tile img {
  width: 96px;
  height: 96px;
}

.session-overlay.win11-session .user-carousel-tile.selected img {
  border-color: transparent;
}

.session-overlay.win11-session .system-icon,
.session-overlay.win11-session .session-mode-btn,
.session-overlay.win11-session .session-settings-btn,
.session-overlay.win11-session .session-status-toggle,
.session-overlay.win11-session .session-status-panel,
.session-overlay.win11-session .modal-content {
  background: transparent;
  border: none;
}

.session-overlay.win11-session .system-icon:hover,
.session-overlay.win11-session .session-mode-btn:hover,
.session-overlay.win11-session .session-settings-btn:hover,
.session-overlay.win11-session .session-status-toggle:hover {
  background: transparent;
  border: none;
}

.session-overlay.win11-session .session-mode-btn.active {
  border-color: transparent;
}

.session-overlay.win11-session .session-electron-banner {
  display: none;
}

.session-overlay.win11-session .login-tip {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 16px;
  width: fit-content;
  max-width: min(520px, calc(100vw - 40px));
