  min-height: 0;
  padding: 0;
  background: transparent;
  border: none;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  color: var(--win11-lock-fg-dim);
}

.session-overlay.win11-session .login-tip i {
  color: var(--win11-lock-fg);
}

.session-overlay.win11-session .session-features-link {
  bottom: 46px;
}

.session-overlay.win11-session .action-button,
.win11-lock-signin {
  background: var(--win11-lock-btn-bg);
  font-size: 13px;
  font-weight: 400;
  padding: 12px;
  color: #fff;
  border: 2px solid transparent;
  border-radius: 4px;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  transform: none;
}

.session-overlay.win11-session .action-button:hover,
.win11-lock-signin:hover {
  background: var(--win11-lock-btn-bg);
  border: 2px solid var(--win11-lock-btn-border);
