.win11-lock-layer {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  color: var(--win11-lock-fg);
  font-family: var(
    --win11-segoe,
    "Segoe UI Variable",
    "Segoe UI",
    system-ui,
    sans-serif
  );
}

.win11-lock-panel {
  position: absolute;
  top: 25%;
  left: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  opacity: 0;
  visibility: hidden;
  transform: translate(-50%, 60px);
  transition:
    opacity 400ms ease-in-out,
    transform 400ms ease-in-out,
    visibility 0s linear 400ms;
}

.session-overlay.win11-session[data-win11-stage="revealed"] .win11-lock-panel {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
  pointer-events: auto;
  transition:
    opacity 400ms ease-in-out,
    transform 400ms ease-in-out,
    visibility 0s linear 0s;
}

.win11-lock-avatar {
  width: 200px;
  height: 200px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--win11-lock-btn-bg);
}

.win11-lock-name {
  margin-top: 8px;
  font-size: 24px;
  font-weight: 500;
  color: var(--win11-lock-fg);
  text-shadow: 0 2px 14px rgba(0, 0, 0, 0.45);
}

.win11-lock-signin {
  margin-top: 24px;
  cursor: pointer;
  font-family: inherit;
}

.win11-lock-signin:focus-visible {
  outline: 2px solid var(--win11-accent);
  outline-offset: 2px;
}

.win11-lock-corner {
  position: absolute;
  right: 24px;
  bottom: 24px;
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--win11-lock-fg);
}

.win11-lock-options {
  position: absolute;
  left: 24px;
  bottom: 72px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: auto;
}

.win11-lock-options .session-selector {
  position: static;
  bottom: auto;
  left: auto;
  z-index: auto;
}

.win11-lock-options .session-modes-grid {
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.win11-lock-options .session-mode-btn {
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 11px;
  min-width: 0;
}

.win11-lock-options .session-mode-btn img {
  width: 18px;
  height: 18px;
}

.win11-lock-layer .login-tip,
.win11-lock-layer .session-support-btn {
  pointer-events: auto;
}

.win11-lock-corner .uicon {
  display: flex;
  align-items: center;
  justify-content: center;
}

.win11-lock-corner .win11-battery {
  display: flex;
  position: relative;
  width: 20px;
  height: 20px;
}

.win11-lock-corner .win11-btFull {
  position: absolute;
  top: 0;
  left: 0;
  overflow: hidden;
  z-index: 0;
}

.win11-lock-corner .win11-charger {
  display: none;
}

.win11-lock-corner .win11-charger svg {
  position: absolute;
  z-index: 1;
}

.win11-lock-battery[data-charging="true"] .win11-charger {
  display: block;
}

.win11-lock-corner .session-settings-btn {
  position: static;
  width: 32px;
  height: 32px;
  border-radius: 6px;
  color: var(--win11-lock-fg);
  pointer-events: auto;
}

.win11-lock-corner .session-settings-btn svg {
  width: 18px;
  height: 18px;
  display: block;
}

.win11-lock-wifi {
  color: var(--win11-lock-fg);
}

.win11-lock-wifi img {
  width: 16px;
  height: 16px;
  filter: invert(1);
  opacity: 0.9;
}

.win11-lock-wifi[data-online="false"] img {
