  border-radius: 50%;
  background: var(--glass);
  color: var(--text-primary);
  cursor: pointer;
  transition:
    background-color 0.2s ease,
    color 0.2s ease;
}

.cam-action-btn:hover:not(:disabled) {
  background: var(--glass-hover);
  border-color: var(--glass-border);
  transform: scale(1.05);
}

.cam-action-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.cam-shutter-btn {
  width: 72px;
  height: 72px;
  flex-shrink: 0;
  border: 3px solid var(--glass-border);
  border-radius: 50%;
  background: transparent;
  padding: 4px;
  cursor: pointer;
  transition:
    background-color 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease;
  position: relative;
}

.cam-shutter-btn:hover {
  border-color: var(--glass-hover);
  transform: scale(1.02);
}

.cam-shutter-btn:active:not(.shutter-snap) {
  transform: scale(0.95);
}

.shutter-inner {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  display: block;
  position: relative;
  transition:
    background-color 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease;
}

.shutter-inner.photo {
  background: var(--text-primary);
  border: 2px solid var(--glass-border);
}

.shutter-inner.video {
  background: var(--error);
}

.shutter-inner.video::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 20px;
  height: 20px;
  background: var(--text-primary);
  border-radius: 4px;
}

.shutter-inner.stop {
  background: var(--error);
  border: 3px solid var(--text-primary);
}

.shutter-inner.stop::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 24px;
  height: 24px;
  background: var(--text-primary);
  border-radius: 2px;
}

.cam-shutter-btn.recording .shutter-inner.video {
  background: var(--error);
  animation: shutter-rec 1s ease-in-out infinite;
}

.cam-shutter-btn.recording .shutter-inner.video::after {
  width: 16px;
  height: 16px;
  border-radius: 2px;
}

@keyframes shutter-rec {
  0%,
  100% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--error) 40%, transparent);
  }
  50% {
    box-shadow: 0 0 0 10px transparent;
  }
}

.cam-shutter-btn.shutter-snap {
  animation: shutter-snap 0.2s ease-out;
}

@keyframes shutter-snap {
  0% {
    transform: scale(1);
  }
  30% {
    transform: scale(0.88);
  }
  70% {
    transform: scale(1.04);
  }
  100% {
    transform: scale(1);
  }
}

.cam-viewfinder-flash {
  position: absolute;
  inset: 0;
  background: white;
  z-index: 20;
  pointer-events: none;
  animation: viewfinder-flash 0.3s ease-out forwards;
}

@keyframes viewfinder-flash {
  0% {
    opacity: 0.6;
  }
  100% {
    opacity: 0;
  }
}

