}
.launchpad-overlay {
  position: fixed;
  inset: 0;
  z-index: 20000;
  background: rgba(0, 0, 0, 0.65);
  backdrop-filter: blur(48px) saturate(1.4);
  -webkit-backdrop-filter: blur(48px) saturate(1.4);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 56px 0 24px;
  box-sizing: border-box;
  overflow: hidden;
  transform-origin: bottom center;
  animation: launchpadIn 0.35s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.launchpad-overlay.launchpad-closing {
  animation: launchpadOut 0.25s cubic-bezier(0.55, 0, 1, 0.45) both;
}

@keyframes launchpadIn {
  from {
    opacity: 0;
    transform: translateY(60px) scale(0.92);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes launchpadOut {
  from {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  to {
    opacity: 0;
    transform: translateY(60px) scale(0.92);
  }
}

.launchpad-close {
  position: fixed;
  top: 20px;
  right: 20px;
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  border: 1px solid var(--glass-border);
  background: var(--glass);
  backdrop-filter: blur(32px) saturate(1.4);
  -webkit-backdrop-filter: blur(32px) saturate(1.4);
  color: var(--text-primary);
  font-size: 14px;
  cursor: pointer;
  z-index: 1;
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  transition:
    background 0.15s,
    transform 0.15s,
    border-color 0.15s;
}

.launchpad-close:hover {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.16);
  transform: scale(1.06);
}

.launchpad-close:active {
  transform: scale(0.94);
}

html[data-theme="light"] .launchpad-close {
  background: rgba(255, 255, 255, 0.92);
  border-color: rgba(0, 0, 0, 0.08);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
}

html[data-theme="light"] .launchpad-close:hover {
  background: #fff;
}

.launchpad-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 20px;
  width: 100%;
  max-width: 1100px;
  height: calc(100vh - 80px);
  max-height: 860px;
  min-height: 0;
  padding: 0 20px 0;
  box-sizing: border-box;
}

.launchpad-search-wrap {
  position: relative;
  width: 280px;
  flex-shrink: 0;
}

.launchpad-search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-secondary);
  font-size: 14px;
  pointer-events: none;
}

.launchpad-search {
  width: 100%;
  height: 36px;
  padding: 0 14px 0 36px;
  border: none;
  border-radius: var(--r-md);
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-primary);
  font-size: 13px;
  font-family: var(--font-ui);
  outline: none;
  box-sizing: border-box;
  transition: background 0.15s;
}
.launchpad-search:focus {
  background: rgba(255, 255, 255, 0.15);
}
.launchpad-search::placeholder {
  color: var(--text-secondary);
}

.launchpad-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
  gap: 16px;
  width: 100%;
  flex: 1;
  min-height: 0;
  max-height: none;
  align-content: start;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 6px 6px 12px;
  box-sizing: border-box;
}

.launchpad-section-label {
  grid-column: 1 / -1;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.7px;
  text-transform: uppercase;
  color: var(--text-secondary);
  opacity: 0.75;
  padding: 10px 6px 2px;
  border-top: 1px solid var(--glass-border);
  margin-top: 4px;
}

.launchpad-section-label:first-child {
  border-top: none;
  margin-top: 0;
  padding-top: 4px;
}

.launchpad-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  padding: 10px 6px 8px;
  border-radius: var(--r-lg);
  transition: transform 0.15s cubic-bezier(0.34, 1.56, 0.64, 1);
  user-select: none;
  -webkit-user-select: none;
}
.launchpad-item:hover {
  transform: scale(1.12);
}
.launchpad-item:active {
  transform: scale(0.96);
}

.launchpad-item-icon-wrap {
  width: 80px;
  height: 80px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--r-md);
  overflow: hidden;
  cursor: pointer;
}

.launchpad-item-icon {
  font-size: 34px;
  color: var(--brand);
  width: 52px;
  height: 52px;
  object-fit: contain;
}

.launchpad-item-label {
  font-size: 12px;
  color: var(--text-primary);
  text-align: center;
  line-height: 1.2;
  max-width: 84px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.launchpad-empty {
  color: var(--text-secondary);
  font-size: 14px;
  padding: 32px 0;
}
.rhythms-container {
  display: flex;
  flex-direction: column;
  height: 100%;
  gap: var(--spacing-md);
  box-sizing: border-box;
  position: relative;
  background: transparent;
}

.rhythms-controls {
  display: flex;
  gap: var(--spacing-md);
  align-items: center;
  flex-wrap: wrap;
}

.rhythms-control-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.rhythms-label {
  font-size: 12px;
  opacity: 0.7;
  color: var(--text-secondary);
}

.rhythms-slider {
  appearance: none;
  width: 120px;
  height: 6px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: var(--r-sm);
  outline: none;
  cursor: pointer;
}

.rhythms-slider::-webkit-slider-thumb {
  appearance: none;
  width: 16px;
  height: 16px;
  background: var(--brand);
  border-radius: 50%;
  cursor: pointer;
  transition:
    background-color 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease;
}

.rhythms-slider::-moz-range-thumb {
  width: 16px;
  height: 16px;
  background: var(--brand);
  border-radius: 50%;
  cursor: pointer;
  border: none;
  transition:
    background-color 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease;
}

.rhythms-slider::-moz-range-thumb:hover {
  background: var(--brand-hover);
  transform: scale(1.1);
}

.rhythms-canvas {
  flex: 1;
  min-height: 0;
  width: 100%;
  background: transparent;
  border-radius: var(--r);
  border: 1px solid var(--glass-border);
  box-shadow:
    0 10px 30px rgba(0, 0, 0, 0.65),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.rhythms-button-group {
  display: flex;
  gap: 4px;
}

.rhythms-mode-btn {
  appearance: none;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  color: var(--text-primary);
  padding: 6px 12px;
  border-radius: var(--r-sm);
  font-size: 13px;
  cursor: pointer;
  transition:
    background-color 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease;
  outline: none;
}

.rhythms-mode-btn:hover {
  background: var(--glass-hover);
  border-color: rgba(255, 255, 255, 0.15);
}

.rhythms-mode-btn.active {
  background: var(--brand);
  border-color: var(--brand);
  color: white;
}

.rhythms-mode-btn.active:hover {
  background: var(--brand-hover);
  border-color: var(--brand-hover);
}

.rhythms-slider-value {
  font-size: 12px;
  color: var(--text-secondary);
  min-width: 32px;
  text-align: center;
}

.rhythms-settings-toggle {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 36px;
  height: 36px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: var(--r);
  color: var(--text-primary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    background-color 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease;
  z-index: 10;
}

.rhythms-settings-toggle:hover {
  background: var(--glass-hover);
  border-color: rgba(255, 255, 255, 0.15);
}

.rhythms-settings-panel {
  position: absolute;
  top: 0;
  right: 0;
  height: 100%;
  width: 0;
  background: rgba(20, 20, 30, 0.85);
  backdrop-filter: blur(32px);
  border-left: 1px solid var(--glass-border);
  overflow: hidden;
  opacity: 0;
  transition:
    background-color 0.2s ease,
    border-color 0.2s ease;
  z-index: 9;
  box-shadow: -10px 0 30px rgba(0, 0, 0, 0.65);
}

.rhythms-settings-panel.open {
  width: 280px;
  opacity: 1;
  padding: var(--spacing-md);
  overflow-y: auto;
}

.rhythms-effect-btn {
  appearance: none;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  color: var(--text-primary);
  padding: 6px 10px;
  border-radius: var(--r-sm);
  font-size: 12px;
  cursor: pointer;
  transition:
    background-color 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease;
  outline: none;
}

.rhythms-effect-btn:hover {
  background: var(--glass-hover);
  border-color: rgba(255, 255, 255, 0.15);
}

.rhythms-effect-btn.active {
  background: var(--brand);
  border-color: var(--brand);
  color: white;
}

.rhythms-effect-btn.active:hover {
  background: var(--brand-hover);
  border-color: var(--brand-hover);
}

.rhythms-toggle-btn {
  appearance: none;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  color: var(--text-primary);
  padding: 8px 16px;
  border-radius: var(--r-sm);
  font-size: 13px;
  cursor: pointer;
  transition:
    background-color 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease;
  outline: none;
  min-width: 100px;
}

.rhythms-toggle-btn:hover {
  background: var(--glass-hover);
  border-color: rgba(255, 255, 255, 0.15);
}

.rhythms-toggle-btn.active {
  background: var(--brand);
  border-color: var(--brand);
  color: white;
}

.rhythms-toggle-btn.active:hover {
  background: var(--brand-hover);
  border-color: var(--brand-hover);
}

.rhythms-color-picker {
  appearance: none;
  width: 100%;
  height: 36px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: var(--r-sm);
  cursor: pointer;
  padding: 2px;
  box-sizing: border-box;
}

.rhythms-color-picker::-webkit-color-swatch-wrapper {
  padding: 0;
}

.rhythms-color-picker::-webkit-color-swatch {
  border: none;
  border-radius: var(--r-sm);
}
.torrent-dropdown {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  background: var(--bg-secondary);
  border: 1px solid var(--glass-border);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  min-width: 200px;
  z-index: 10000;
  padding: 4px 0;
  border-radius: 6px;
  backdrop-filter: blur(32px);
}

.app-menubar-item.active .torrent-dropdown {
  display: block;
}

.dropdown-item {
  padding: 6px 35px 6px 28px;
  cursor: default;
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: relative;
  white-space: nowrap;
  color: var(--text-primary);
  transition: background 0.1s;
  font-size: 12px;
}

.dropdown-item:hover {
  background: rgba(var(--brand-rgb, 99, 102, 241), 0.15);
  color: var(--text-primary);
}

.dropdown-item.disabled {
  color: var(--text-secondary);
  opacity: 0.5;
  pointer-events: none;
}

.dropdown-item .checkmark {
  position: absolute;
  left: 10px;
  font-size: 10px;
  color: var(--brand);
}

.dropdown-item .shortcut {
  color: var(--text-secondary);
  font-size: 11px;
  opacity: 0.7;
}

.dropdown-separator {
  height: 1px;
  background: var(--glass-border);
  margin: 4px 0;
}

.torrent-main-layout {
  display: flex;
  height: 100%;
  background: var(--bg-primary);
}
.torrent-sidebar {
  width: 140px;
  background: var(--bg-secondary);
  border-right: 1px solid var(--glass-border);
  display: flex;
  flex-direction: column;
  padding: 4px 0;
  flex-shrink: 0;
}

.torrent-sidebar-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  color: var(--text-secondary);
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
  font-size: 12px;
  user-select: none;
  border-radius: 0;
  border-left: 3px solid transparent;
}

.torrent-sidebar-item:hover {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-primary);
}

.torrent-sidebar-item.active {
  background: rgba(var(--brand-rgb, 99, 102, 241), 0.15);
  color: var(--brand);
  border-left-color: var(--brand);
}

.torrent-sidebar-item i {
  width: 16px;
  text-align: center;
  font-size: 13px;
  opacity: 0.8;
}

.torrent-sidebar-item.active i {
  opacity: 1;
}

.torrent-queue-badge {
  margin-left: auto;
  background: rgba(255, 255, 255, 0.25);
  color: #fff;
  font-size: 10px;
  font-weight: 600;
  padding: 1px 5px;
  border-radius: 8px;
  line-height: 1.4;
}

.torrent-sidebar-item:not(.active) .torrent-queue-badge {
  background: var(--brand);
  color: #fff;
}

.torrent-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-width: 0;
}

.torrent-toolbar {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 4px 8px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--glass-border);
  flex-shrink: 0;
}

.torrent-tool-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  padding: 6px 10px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 3px;
  color: var(--text-secondary);
  font-size: 13px;
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
  white-space: nowrap;
  min-width: 32px;
}

.torrent-tool-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-primary);
}

.torrent-tool-btn--text {
  gap: 6px;
  font-size: 12px;
  padding: 5px 10px;
}

.torrent-tool-btn--danger {
  color: var(--error, #e53935);
}

.torrent-tool-btn--danger:hover {
  border-color: var(--error, #e53935);
  background: rgba(229, 57, 53, 0.08);
  color: var(--error, #e53935);
}

.torrent-toolbar-separator {
  width: 1px;
  height: 20px;
  background: var(--glass-border);
  margin: 0 3px;
  flex-shrink: 0;
}

.torrent-list-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.torrent-list-header {
  display: grid;
  grid-template-columns: 24px 1fr 70px 100px 70px 70px 70px 50px;
  gap: 4px;
  padding: 4px 8px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--glass-border);
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
  align-items: center;
  flex-shrink: 0;
  text-transform: uppercase;
  letter-spacing: var(--ls-wide);
}

.torrent-list {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
}

.torrent-row {
  display: grid;
  grid-template-columns: 24px 1fr 70px 100px 70px 70px 70px 50px;
  gap: 4px;
  padding: 4px 8px;
  border-bottom: 1px solid var(--glass-border);
  align-items: center;
  cursor: pointer;
  transition: background 0.1s;
  font-size: 12px;
}

.torrent-row:hover {
  background: rgba(255, 255, 255, 0.05);
}

.torrent-row--active {
  background: rgba(var(--brand-rgb, 99, 102, 241), 0.12);
}

.torrent-checkbox {
  width: 13px;
  height: 13px;
  cursor: pointer;
  accent-color: var(--brand);
  flex-shrink: 0;
  appearance: none;
  -webkit-appearance: none;
  border: 1px solid var(--glass-border);
  border-radius: 2px;
  background: var(--bg-primary);
  position: relative;
}

.torrent-checkbox:checked {
  background: var(--brand);
  border-color: var(--brand);
}

.torrent-checkbox:checked::after {
  content: "✓";
  position: absolute;
  color: #fff;
  font-size: 9px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.torrent-name {
  font-size: 12px;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.torrent-size {
  font-size: 11px;
  color: var(--text-secondary);
  text-align: right;
}

.torrent-progress-cell {
  display: flex;
  align-items: center;
  gap: 6px;
}

.torrent-progress-bar-small {
  flex: 1;
  height: 4px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  overflow: hidden;
}

.torrent-progress-fill {
  height: 100%;
  background: linear-gradient(
    90deg,
    var(--brand),
    rgba(var(--brand-rgb, 99, 102, 241), 0.8)
  );
  border-radius: 2px;
  transition: width 0.2s;
}

.torrent-progress-text {
  font-size: 10px;
  color: var(--text-secondary);
  min-width: 30px;
  text-align: right;
}

.torrent-status {
