  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 4px;
}

.torrent-status--downloading {
  color: #4caf50;
}

.torrent-status--completed {
  color: #2196f3;
}

.torrent-status--paused {
  color: #ff9800;
}

.torrent-down,
.torrent-up {
  font-size: 11px;
  color: var(--text-secondary);
  text-align: right;
}

.torrent-ratio {
  font-size: 11px;
  color: var(--text-secondary);
  text-align: right;
}

.torrent-ratio--good {
  color: #4caf50;
}

.torrent-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--text-secondary);
  padding: 32px;
  text-align: center;
}

.torrent-empty-icon {
  font-size: 36px;
  margin-bottom: 14px;
  opacity: 0.35;
}

.torrent-empty-title {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 6px;
  color: var(--text-primary);
}

.torrent-empty-desc {
  font-size: 12px;
  opacity: 0.6;
}

.torrent-queue-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--glass-border);
}

.torrent-queue-position {
  font-size: 11px;
  color: var(--text-secondary);
  min-width: 24px;
}

.torrent-queue-name {
  flex: 1;
  font-size: 12px;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.torrent-queue-remove-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 2px 5px;
  border-radius: 3px;
  font-size: 11px;
  transition:
    color 0.15s,
    background 0.15s;
}

.torrent-queue-remove-btn:hover {
  color: var(--error, #e53935);
  background: rgba(229, 57, 53, 0.08);
}

.torrent-details-panel {
  height: 200px;
  background: var(--bg-secondary);
  border-top: 1px solid var(--glass-border);
  overflow-y: auto;
  flex-shrink: 0;
}

.torrent-details-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--text-secondary);
  font-size: 12px;
  opacity: 0.6;
}

.torrent-details-content {
  padding: 12px 14px;
}

.torrent-details-top {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 12px;
}

.torrent-details-name {
  flex: 1;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.4;
}

.torrent-details-status {
  padding: 2px 8px;
  border-radius: 3px;
