  text-transform: uppercase;
  letter-spacing: var(--ls-wide);
}

.torrent-details-status--downloading {
  background: rgba(76, 175, 80, 0.15);
  color: #4caf50;
}

.torrent-details-status--completed {
  background: rgba(33, 150, 243, 0.15);
  color: #2196f3;
}

.torrent-details-status--paused {
  background: rgba(255, 152, 0, 0.15);
  color: #ff9800;
}

.torrent-details-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px 10px;
  margin-bottom: 8px;
}

.torrent-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.torrent-stat-label {
  font-size: 10px;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: var(--ls-wide);
}

.torrent-stat-value {
  font-size: 12px;
  color: var(--text-primary);
}

.torrent-detail-hash {
  font-family: monospace;
  font-size: 10px;
