}

.torrent-file-name {
  font-size: 11px;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.torrent-file-size {
  font-size: 10px;
  color: var(--text-secondary);
  text-align: right;
}

.torrent-file-progress {
