  align-items: center;
  justify-content: center;
  z-index: 99999;
  animation: modal-overlay-fade 0.2s ease;
}

.clock-alarm-dialog {
  background: var(--menu-bg);
  backdrop-filter: blur(32px) saturate(180%);
  border-radius: 20px;
  padding: 32px;
  text-align: center;
  border: 1px solid var(--glass-border);
  box-shadow: var(--shadow-depth);
  animation: modal-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  min-width: 300px;
}

.clock-alarm-dialog-icon {
  font-size: 3em;
  margin-bottom: 12px;
}

.clock-alarm-dialog-time {
  font-size: 2.5em;
  font-weight: 300;
  color: var(--text-primary);
  font-family: var(--font-mono);
  letter-spacing: 2px;
}

.clock-alarm-dialog-label {
  font-size: 1em;
  color: var(--text-secondary);
  margin: 8px 0 24px;
}

.clock-alarm-dialog-buttons {
  display: flex;
  gap: 10px;
  justify-content: center;
}

.clock-alarm-dialog-btn {
  padding: 10px 20px;
  border-radius: 24px;
  border: none;
  font-size: 0.85em;
  cursor: pointer;
  transition: all 0.15s ease;
  font-family: inherit;
}

.clock-alarm-dialog-btn.snooze {
  background: var(--brand-dim);
  border: 1px solid var(--brand);
  color: var(--brand);
}

.clock-alarm-dialog-btn.snooze:hover {
  background: var(--brand);
  color: var(--text-on-brand);
}

.clock-alarm-dialog-btn.dismiss {
  background: var(--glass);
  border: 1px solid var(--glass-border);
  color: var(--text-primary);
}

.clock-alarm-dialog-btn.dismiss:hover {
  background: var(--glass-hover);
}

@keyframes modal-pop {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes modal-overlay-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.clock-stopwatch-laps::-webkit-scrollbar,
.clock-alarms-list::-webkit-scrollbar {
  width: 6px;
}

.clock-stopwatch-laps::-webkit-scrollbar-track,
.clock-alarms-list::-webkit-scrollbar-track {
  background: transparent;
}

.clock-stopwatch-laps::-webkit-scrollbar-thumb,
.clock-alarms-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 3px;
}
