}

.connect-hint {
  font-size: 12px;
  margin: 0;
}

.connect-hint.error {
  color: var(--error);
}

.remote-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 20px;
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s;
}

.remote-btn.primary {
  background: var(--brand);
  color: #fff;
}

.remote-btn.primary:hover {
  opacity: 0.88;
}

.remote-btn.primary:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.remote-btn.danger {
  background: var(--error);
  color: #fff;
}

.remote-btn.danger:hover {
  opacity: 0.88;
}

.remote-btn.secondary {
  background: var(--glass);
  color: var(--text-primary);
  border: 1px solid var(--glass-border);
}

.remote-btn.secondary:hover {
  background: var(--bg-primary);
}

.remote-btn.small {
  padding: 6px 14px;
  font-size: 12px;
}

.viewer-screen {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
}

.viewer-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--glass-border);
  flex-shrink: 0;
}

.viewer-status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-secondary);
}

.viewer-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--success);
  flex-shrink: 0;
}

.viewer-status-dot.disconnected {
  background: var(--error);
}

.viewer-room-badge {
  background: var(--glass);
  padding: 4px 12px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 4px;
  color: var(--text-primary);
  border: 1px solid var(--glass-border);
  user-select: text;
}

.viewer-audio-indicator {
  font-size: 13px;
  color: var(--success);
  display: flex;
  align-items: center;
}

.video-container {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #000;
  position: relative;
  overflow: hidden;
}

.video-container video {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}

.video-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
