}

.video-overlay.hidden {
  display: none;
}

.video-overlay p {
  color: var(--text-secondary);
  font-size: 14px;
  margin: 0;
}

.spinner {
  width: 36px;
  height: 36px;
  border: 3px solid var(--glass-border);
  border-top-color: var(--brand);
  border-radius: 50%;
  animation: remote-spin 0.8s linear infinite;
}

@keyframes remote-spin {
  to {
    transform: rotate(360deg);
  }
}

.host-body {
  flex: 1;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  overflow-y: auto;
}

.host-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.host-label {
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 500;
}

.host-select {
  background: var(--bg-primary);
  border: 1px solid var(--glass-border);
  border-radius: 8px;
  padding: 8px 12px;
  color: var(--text-primary);
  font-size: 13px;
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
  outline: none;
}

.host-select:focus {
  border-color: var(--brand);
}

.host-room {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px;
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  backdrop-filter: blur(32px);
}

.host-room-code {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 10px;
  text-align: center;
  color: var(--brand);
  font-family: "JetBrains Mono", monospace;
  padding: 10px;
  background: var(--bg-primary);
  border-radius: 8px;
  border: 1px solid var(--glass-border);
  user-select: text;
}

.host-hint {
  font-size: 11px;
  color: var(--text-secondary);
  text-align: center;
  margin: 0;
}

.host-actions {
  display: flex;
  gap: 8px;
  margin-top: auto;
}

.host-log {
  border-top: 1px solid var(--glass-border);
