.aquarium-root {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: transparent;
  overflow: hidden;
}

.aquarium-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  background: linear-gradient(
    180deg,
    rgba(12, 72, 130, 0.34),
    rgba(8, 52, 96, 0.28)
  );
  border-bottom: 1px solid rgba(125, 211, 252, 0.22);
  box-shadow:
    inset 0 1px 0 rgba(125, 211, 252, 0.18),
    0 2px 12px rgba(0, 40, 80, 0.22);
  backdrop-filter: blur(16px) saturate(140%);
  -webkit-backdrop-filter: blur(16px) saturate(140%);
  flex-shrink: 0;
  min-width: 0;
}

.aquarium-toolbar-left {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: 1px;
}

.aquarium-toolbar-left::-webkit-scrollbar {
  display: none;
}

.aquarium-toolbar-center {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #bae6fd;
  font-size: 12px;
  flex-shrink: 0;
  white-space: nowrap;
}

.aquarium-count {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  background: rgba(14, 95, 160, 0.36);
  border: 1px solid rgba(125, 211, 252, 0.28);
  border-radius: 20px;
  color: #e0f2fe;
  font-weight: 700;
  box-shadow:
    0 2px 8px rgba(0, 40, 80, 0.22),
    inset 0 1px 0 rgba(125, 211, 252, 0.18);
  font-size: 12px;
}

.aquarium-hint {
  opacity: 0.78;
  font-size: 11px;
  color: #bae6fd;
  font-weight: 500;
}

.aquarium-btn {
  appearance: none;
  border: 1px solid rgba(125, 211, 252, 0.32);
  background: rgba(14, 95, 160, 0.28);
  color: #e0f2fe;
  padding: 6px 13px;
  border-radius: 20px;
  font-size: 12px;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
