  -webkit-backdrop-filter: blur(8px);
}

.aquarium-btn:hover {
  background: rgba(28, 115, 185, 0.38);
  border-color: rgba(125, 211, 252, 0.48);
  transform: translateY(-1px);
  box-shadow:
    0 4px 14px rgba(0, 60, 110, 0.28),
    inset 0 1px 0 rgba(125, 211, 252, 0.28);
}

.aquarium-btn:active {
  transform: translateY(0px) scale(0.98);
}

.aquarium-btn.primary {
  background: linear-gradient(180deg, #7ad8ff, #2ec4ff, #0ea5e9);
  border-color: rgba(255, 255, 255, 0.82);
  color: #ffffff;
  text-shadow: 0 1px 0 rgba(0, 60, 100, 0.35);
  box-shadow:
    0 3px 12px rgba(14, 165, 233, 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    inset 0 -1px 0 rgba(0, 80, 120, 0.22);
}

.aquarium-btn.primary:hover {
  background: linear-gradient(180deg, #8ee0ff, #38c8ff, #10aef0);
  box-shadow:
    0 5px 16px rgba(14, 165, 233, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.aquarium-btn.icon {
