.aquarium-toolbar-right .aquarium-btn.icon:hover {
  background: rgba(28, 115, 185, 0.52);
  border-color: rgba(125, 211, 252, 0.52);
}

.aquarium-toolbar-right .aquarium-btn.icon.active {
