  color: #7dd3ff;
  box-shadow:
    inset 0 2px 8px rgba(0, 20, 50, 0.42),
    0 1px 0 rgba(125, 211, 252, 0.22);
}

.aquarium-stage {
  position: relative;
  flex: 1;
  min-height: 0;
  background: transparent;
  overflow: hidden;
  cursor: crosshair;
  contain: strict;
}

.aquarium-stage::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      ellipse 700px 260px at 18% 8%,
      rgba(56, 189, 248, 0.18),
      transparent 62%
    ),
    radial-gradient(
      ellipse 520px 220px at 82% 14%,
      rgba(14, 165, 233, 0.14),
      transparent 60%
    ),
    radial-gradient(
      ellipse 800px 340px at 50% 85%,
      rgba(14, 95, 160, 0.16),
      transparent 70%
    );
  pointer-events: none;
  z-index: 1;
}

#aquarium-canvas {
  display: block;
  width: 100%;
  height: 100%;
  position: relative;
  z-index: 0;
  will-change: width, height;
  transform: translateZ(0);
}

.aquarium-glass {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    linear-gradient(
      105deg,
      rgba(125, 211, 252, 0.16) 0%,
      transparent 24%,
      transparent 80%,
      rgba(56, 189, 248, 0.1) 100%
    ),
    linear-gradient(180deg, rgba(125, 211, 252, 0.14) 0%, transparent 18%);
  border-left: 1px solid rgba(125, 211, 252, 0.18);
  border-right: 1px solid rgba(125, 211, 252, 0.1);
  box-shadow: inset 0 1px 0 rgba(125, 211, 252, 0.22);
}

.aquarium-surface {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 22px;
  pointer-events: none;
  z-index: 3;
  background: linear-gradient(
    to bottom,
    rgba(56, 189, 248, 0.28),
    rgba(14, 95, 160, 0.12) 55%,
    transparent
  );
  opacity: 0.95;
  border-bottom: 1px solid rgba(125, 211, 252, 0.18);
}

.aquarium-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  box-shadow:
    inset 0 0 90px rgba(0, 60, 110, 0.22),
    inset 0 0 40px rgba(14, 95, 160, 0.12),
    inset 0 1px 0 rgba(125, 211, 252, 0.18);
  border-top: 1px solid rgba(125, 211, 252, 0.16);
  border-radius: 0;
}

.aquarium-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 12px;
  background: rgba(12, 72, 130, 0.28);
  border-top: 1px solid rgba(125, 211, 252, 0.2);
  box-shadow: inset 0 1px 0 rgba(125, 211, 252, 0.14);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  font-size: 11px;
  color: #bae6fd;
  font-weight: 500;
  flex-shrink: 0;
}

.aquarium-bubble-fab {
  position: absolute;
  right: 14px;
  bottom: 14px;
  z-index: 6;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  border: 1px solid rgba(125, 211, 252, 0.42);
  background: radial-gradient(
    circle at 30% 28%,
    rgba(255, 255, 255, 0.96) 0%,
    rgba(186, 230, 253, 0.92) 18%,
    rgba(56, 189, 248, 0.62) 42%,
    rgba(14, 95, 160, 0.44) 72%,
    rgba(12, 72, 130, 0.32) 100%
  );
  box-shadow:
    0 6px 18px rgba(0, 60, 110, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.92),
    inset 0 -8px 14px rgba(14, 65, 115, 0.22);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #0c4a6e;
  font-size: 17px;
  cursor: pointer;
  transition:
    transform 0.14s ease,
    box-shadow 0.14s ease,
    filter 0.14s ease;
  animation: bubble-float 3.2s ease-in-out infinite;
}

.aquarium-bubble-fab:hover {
  transform: translateY(-2px) scale(1.06);
  box-shadow:
    0 10px 22px rgba(0, 60, 110, 0.36),
    inset 0 1px 0 rgba(255, 255, 255, 0.98);
  filter: brightness(1.06);
}

.aquarium-bubble-fab:active {
  transform: scale(0.96);
}

.aquarium-bubble-fab::after {
  content: "";
  position: absolute;
  top: 7px;
  left: 10px;
  width: 12px;
  height: 9px;
  border-radius: 50%;
  background: radial-gradient(
    ellipse at center,
    rgba(255, 255, 255, 0.92),
    transparent 72%
  );
  pointer-events: none;
}

@keyframes bubble-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-3px);
  }
}

.aquarium-status #aquarium-status-text.flash {
  animation: aqua-flash 0.4s ease;
