  border-color: rgba(248, 113, 113, 0.38);
  color: #fee2e2;
}

.aquarium-btn.danger:hover {
  background: rgba(200, 38, 60, 0.44);
  border-color: rgba(248, 113, 113, 0.58);
}

@keyframes aqua-flash {
